(function () {
  'use strict';
  var translations = {"TRANG CHỦ": "HOME", "ỨNG DỤNG": "APPS", "Khám phá Apps": "Explore Apps", "TRÒ CHƠI": "GAMES", "Khu trò chơi": "Games Hub", "CÔNG CỤ": "TOOLS", "Khám phá Công cụ": "Explore Tools", "XỔ SỐ": "LOTTERY", "ĐI CHỢ": "SHOPPING", "TIN TỨC": "NEWS", "HỌC VIỆN MAY MẶC": "GARMENT ACADEMY", "THƯ VIỆN KIẾN THỨC DỆT MAY": "TEXTILE & APPAREL KNOWLEDGE LIBRARY", "Vật liệu & dệt": "Materials & Textiles", "Thiết kế & sản phẩm": "Design & Product Development", "Sản xuất": "Manufacturing", "Chất lượng": "Quality", "Quản trị & thương mại": "Business & Merchandising", "Từ điển": "Dictionary", "← Thư viện Garment Academy": "← Garment Academy Library", "Trang chủ": "Home", "Ứng dụng": "Apps", "Công cụ": "Tools", "Trò chơi": "Games", "HỌC VIỆN": "ACADEMY", "Tài liệu tham khảo": "References", "Nguồn": "References", "BẮT ĐẦU": "GET STARTED", "APPNHO": "APPNHO", "Mở menu": "Open menu", "Tìm kiếm": "Search", "Tất cả nhóm nội dung": "All content groups", "Lọc theo nhóm": "Filter by group", "Không tìm thấy nội dung phù hợp.": "No matching content was found.", "Tất cả": "All", "In": "Print", "Tải xuống": "Download", "Công nghệ cắt vải và chuẩn bị bán thành phẩm": "Fabric Cutting and Cut-component Preparation", "Luồng chuẩn bị và cắt": "Pre-production and Cutting Workflow", "01. Tổng quan quy trình chuẩn bị sản xuất": "01. Overview of Pre-production Preparation", "Phân tích kỹ thuật và thực hành": "Technical Analysis and Workshop", "02. Kiểm tra vải đầu vào trước khi trải": "02. Incoming Fabric Inspection Before Spreading", "03. Hệ thống 4-point và phân loại lỗi vải": "03. The 4-Point System and Fabric Defect Classification", "04. Shade band, lot và quản lý màu": "04. Shade Bands, Lots and Colour Control", "05. Relaxation và ổn định vải trước cắt": "05. Fabric Relaxation and Stabilisation Before Cutting", "06. Kiểm soát khổ vải và usable width": "06. Fabric Width and Usable Width Control", "07. Nguyên tắc spreading và lay": "07. Spreading and Lay Principles", "08. One-way, face-to-face và nap direction": "08. One-way, Face-to-face and Nap Direction", "09. Spreading tension, ply alignment và lay end": "09. Spreading Tension, Ply Alignment and Lay Ends", "10. Spreading defects và cách xử lý": "10. Spreading Defects and Corrective Actions", "11. Pattern, marker và cut order": "11. Patterns, Markers and Cut Orders", "12. Grainline, bias và hướng chi tiết": "12. Grainline, Bias and Component Orientation", "13. Marker efficiency và fabric utilization": "13. Marker Efficiency and Fabric Utilisation", "14. Marker planning theo size ratio": "14. Marker Planning by Size Ratio", "15. Máy cắt đầu bàn và dao cắt tay": "15. End-cutters and Hand-held Cutting Tools", "16. Straight knife và round knife": "16. Straight-knife and Round-knife Machines", "17. Band knife và cắt chi tiết nhỏ": "17. Band Knives and Small-component Cutting", "18. Máy cắt tự động CNC": "18. CNC Automatic Cutting Systems", "19. Laser, ultrasonic và công nghệ cắt đặc thù": "19. Laser, Ultrasonic and Specialised Cutting Technologies", "20. Notch, drill hole và dấu kỹ thuật": "20. Notches, Drill Holes and Technical Marks", "21. Numbering và shade control": "21. Numbering and Shade Control", "22. Bundling, ticket và phối kiện": "22. Bundling, Tickets and Bundle Assembly", "23. Fusing và ép keo dựng": "23. Fusing and Interlining Bonding", "24. Kiểm tra bán thành phẩm sau cắt": "24. Cut-component Inspection", "25. Tính định mức vải và tiêu hao": "25. Fabric Consumption and Allowance Calculations", "26. Cut order planning và kiểm soát tiến độ": "26. Cut-order Planning and Progress Control", "27. Hồ sơ bàn giao từ cutting sang sewing": "27. Cutting-to-sewing Handover Records", "Tài liệu tham khảo và cách sử dụng": "References and How to Use This Material", "Máy cắt tự động CNC điều khiển đường cắt theo dữ liệu số, thường kết hợp bàn hút chân không, đầu cắt và phần mềm nhận dữ liệu marker. Hệ thống có thể nâng độ lặp lại và giảm phụ thuộc thao tác thủ công, nhưng kết quả vẫn phụ thuộc chất lượng dữ liệu rập, marker, lay, vật liệu và thiết lập máy.": "CNC automatic cutting systems control the cutting path from digital data and commonly combine a vacuum table, cutting head and software that imports marker files. They can improve repeatability and reduce dependence on manual handling, but the result still depends on pattern, marker, lay and material data, as well as machine settings.", "Trước khi cắt, kiểm tra phiên bản file, đơn vị đo, gốc tọa độ, khổ bàn, usable width và chiều dài lay. Xác nhận dữ liệu marker khớp với cut order và hướng vật liệu. Kiểm tra bàn hút, giấy phủ, màng, dao, đá mài và cảm biến theo quy trình của nhà sản xuất. Với vật liệu nhiều lớp, lực hút phải đủ giữ ổn định nhưng không làm biến dạng hoặc hút lệch lớp.": "Before cutting, verify the file revision, measurement units, coordinate origin, table width, usable width and lay length. Confirm that the marker data matches the cut order and material orientation. Inspect the vacuum table, covering paper, film, blade, sharpening stone and sensors in accordance with the manufacturer's procedure. For multi-ply materials, vacuum pressure must hold the lay securely without distorting it or shifting the plies.", "Chạy thử đường cắt trên vật liệu/lay đại diện trước khi phát hành hàng loạt. Kiểm kích thước chi tiết, notch, drill, đường cong và độ vuông lớp. Theo dõi dấu hiệu dao cùn như mép xơ, đường cắt không xuyên hết hoặc lệch ở góc. Khi lỗi xảy ra, lưu file chương trình, thông số, mã dao và vị trí lỗi để phân tích; không chỉ tăng tốc độ hoặc thay dao theo cảm tính.": "Run a trial cut on representative material and a representative lay before releasing the job for production. Check component dimensions, notches, drill holes, curves and ply squareness. Watch for signs of a blunt blade, such as frayed edges, incomplete cuts or deviation at corners. When a defect occurs, retain the program file, settings, blade identification and defect location for analysis; do not simply increase speed or replace the blade by guesswork.", "Ví dụ: một marker được xuất sai đơn vị có thể tạo đường cắt lệch tỷ lệ dù máy chạy đúng chương trình. Vì vậy bước xác nhận kích thước chuẩn trên file và mẫu cắt đầu tiên là bắt buộc. Người vận hành cần đối chiếu ít nhất một vài kích thước chuẩn đã được kỹ thuật quy định trước khi chạy cả lay.": "For example, a marker exported in the wrong units can produce incorrectly scaled cutting paths even when the machine executes the program correctly. The file dimensions and first cut sample must therefore be verified. Before cutting the full lay, the operator should compare several reference dimensions specified by the technical team.", "Hồ sơ máy gồm model, phiên bản phần mềm, loại đầu cắt, thông số được duyệt theo vật liệu, lịch bảo trì, kiểm tra hút chân không, chương trình cắt và kết quả first-off. Lưu chương trình theo mã hàng và phiên bản, không ghi đè file cũ.": "The machine record should include the model, software version, cutting-head type, material-approved settings, maintenance schedule, vacuum checks, cutting program and first-off results. Store programs by style and revision; do not overwrite earlier files.", "Không giả định máy CNC tự loại bỏ lỗi do marker hoặc lay. Máy có thể lặp lại chính xác một dữ liệu sai; kiểm soát đầu vào vẫn là điều kiện quyết định.": "Do not assume that CNC equipment will correct errors in a marker or lay. A machine can reproduce incorrect input data with great precision; control of the input remains decisive.", "Trước khi chạy CNC, xác nhận file marker, gốc tọa độ, phiên bản rập, chân không giữ vải và thông số theo manual máy; chạy thử mẫu đầu để kiểm tra đường cắt.": "Before operating the CNC cutter, verify the marker file, coordinate origin, pattern revision, vacuum hold-down and settings against the machine manual. Run a first-off sample to check the cutting path.", "Laser và ultrasonic là các phương pháp xử lý/cắt vật liệu có cơ chế khác với dao cơ học. Chúng chỉ phù hợp với một số tổ hợp vật liệu và cấu trúc; lựa chọn cần đánh giá chất lượng mép, biến đổi nhiệt, độ bền liên kết, tốc độ, chi phí và an toàn.": "Laser and ultrasonic processes cut or process materials through mechanisms different from mechanical blades. They are suitable only for certain material and construction combinations. Selection should consider edge quality, thermal effects, bond integrity, throughput, cost and safety.", "Laser dùng năng lượng tập trung để gia công vật liệu, có thể tạo mép kín nhiệt ở một số vật liệu tổng hợp nhưng cũng có nguy cơ cháy xém, đổi màu, phát sinh khói hoặc làm biến tính vùng cắt. Ultrasonic sử dụng dao động tần số cao kết hợp lực ép, thường được ứng dụng cho một số vật liệu nhiệt dẻo hoặc cấu trúc nhiều lớp. Khả năng hàn/cắt phụ thuộc vật liệu, cấu hình đầu rung, lực ép và điều kiện máy. Không thể suy ra tính phù hợp chỉ từ tên xơ trên nhãn.": "Laser processing uses concentrated energy and can produce a thermally sealed edge in some synthetic materials, but it may also cause scorching, colour change, fumes or material alteration in the cut zone. Ultrasonic processing combines high-frequency vibration with applied pressure and is used with selected thermoplastic materials and multilayer constructions. Welding or cutting performance depends on the material, horn configuration, applied force and machine conditions. Suitability cannot be determined from the fibre name on a label alone.", "Quy trình đánh giá cần lấy mẫu đại diện, xác định mặt cắt, tốc độ, năng lượng/công suất và điều kiện thông gió theo hướng dẫn thiết bị. Kiểm tra mép cắt dưới ánh sáng phù hợp, độ cứng/giòn, biến dạng, mùi hoặc khói bất thường và độ bền sau xử lý. Với sản phẩm tiếp xúc da hoặc yêu cầu an toàn đặc biệt, phải xem xét các yêu cầu hóa chất và phát thải liên quan.": "Evaluation should use representative samples and establish the cut profile, speed, energy or power, and ventilation conditions in accordance with the equipment instructions. Inspect the cut edge under suitable lighting and assess hardness or brittleness, distortion, unusual odour or fumes, and post-process strength. For skin-contact products or products subject to specific safety requirements, relevant chemical and emission requirements must also be considered.", "Ví dụ: một loại vải phủ có thể cắt laser sạch ở mẫu nhỏ nhưng khi chạy liên tục, nhiệt tích tụ làm mép đổi màu. Cần thử ở điều kiện sản xuất đại diện, không phê duyệt chỉ từ một mẫu ngắn. Nếu phải dùng lớp đệm hoặc hút khói, các điều kiện đó phải được ghi thành tiêu chuẩn vận hành.": "For example, a coated fabric may produce a clean laser cut on a small sample, while accumulated heat during continuous production discolours the edge. Trials must represent production conditions; a short sample alone is not sufficient for approval. If a backing layer or fume extraction is required, these conditions must be included in the operating standard.", "Hồ sơ phê duyệt nên có mã vật liệu, cấu trúc, model thiết bị, cấu hình đầu cắt, thông số thử, kết quả ngoại quan, độ bền và điều kiện an toàn. Mỗi thay đổi vật liệu hoặc lớp phủ cần đánh giá lại.": "The approval record should identify the material code and construction, equipment model, cutting-head configuration, trial settings, appearance and strength results, and safety conditions. Any change in material or coating requires reassessment.", "Không tự đưa ra mức công suất hoặc tần số áp dụng chung. Các thông số phải theo manual, hướng dẫn nhà cung cấp và thử nghiệm được phê duyệt tại nhà máy.": "Do not prescribe universal power or frequency settings. Parameters must follow the equipment manual, supplier guidance and trials approved by the factory.", "Đánh giá tương thích giữa công nghệ và vật liệu, gồm hiện tượng cháy cạnh, nóng chảy, biến màu hoặc phát sinh khói; chỉ dùng cửa sổ thông số đã được thử và duyệt.": "Assess process-material compatibility, including edge scorching, melting, colour change and fume generation. Use only parameter ranges that have been tested and approved.", "Notch, drill hole và các dấu kỹ thuật giúp định vị chi tiết trong quá trình lắp ráp. Chúng là dữ liệu công nghệ được chuyển từ rập sang bán thành phẩm; sai vị trí hoặc sai cách tạo dấu có thể làm lệch đường ráp, sai đối xứng hoặc để lại dấu không chấp nhận trên thành phẩm.": "Notches, drill holes and other technical marks locate components during assembly. They transfer technical information from the pattern to the cut components. Incorrect positioning or marking methods can shift seam alignment, disturb symmetry or leave unacceptable marks on the finished garment.", "Notch thường dùng để xác định điểm ráp, điểm giữa hoặc vị trí kiểm soát; drill hole có thể đánh dấu vị trí túi, ly, chi tiết trang trí hoặc điểm định vị theo thiết kế. Dấu có thể được tạo bằng dao, mũi khoan, bút dấu hoặc phương pháp khác. Chọn phương pháp theo loại vải, độ dày lay, độ bền màu và yêu cầu ngoại quan. Dấu phải đủ nhìn cho người may nhưng không làm thủng hoặc để lại vết ngoài vùng cho phép.": "Notches commonly identify matching points, centre points or control positions. Drill holes may locate pockets, pleats, decorative components or other design reference points. Marks can be made with a blade, drill, marking pen or another method. Select the method according to fabric type, lay height, colourfastness and appearance requirements. Marks must be visible to sewing operators without perforating the fabric or leaving traces outside permitted areas.", "Trước cắt, đối chiếu dấu trên pattern với tech pack và mẫu duyệt. Sau cắt, kiểm vị trí dấu trên lớp trên, giữa và dưới khi rủi ro sai lệch cao. Với vải có bề mặt nhạy cảm, thử bút/dấu trên mẫu và kiểm tra sau giặt hoặc hoàn tất nếu cần. Nếu dấu bị mất hoặc không rõ, không tự đánh dấu lại theo ước lượng; cần dùng dưỡng hoặc tài liệu chuẩn.": "Before cutting, compare the pattern marks with the tech pack and approved sample. After cutting, check mark positions on the top, middle and bottom plies when the risk of variation is high. For fabrics with sensitive surfaces, test the marking method on a sample and check it after washing or finishing where required. If a mark is missing or unclear, do not recreate it by estimation; use a template or approved reference document.", "Ví dụ: vị trí drill hole cho túi phải khớp với điểm đặt túi trên thân. Nếu dấu dịch 5 mm, túi có thể lệch so với đường trang trí hoặc đường may. Mẫu kiểm nên đo từ một điểm chuẩn ổn định trên rập, không đo từ mép cắt có thể biến thiên.": "For example, a pocket drill-hole position must match the pocket placement point on the body panel. A 5 mm shift can misalign the pocket with a decorative feature or seam. The inspection sample should be measured from a stable pattern datum, not from a cut edge that may vary.", "Bảng kiểm dấu kỹ thuật gồm loại dấu, mục đích, vị trí chuẩn, phương pháp tạo, dung sai, vật liệu áp dụng và kết quả kiểm. Các dấu đặc biệt phải được thể hiện trên operation bulletin để chuyền may hiểu đúng.": "The technical-mark inspection sheet should record the mark type, purpose, reference position, marking method, tolerance, applicable material and inspection result. Special marks must also appear in the operation bulletin so the sewing line can interpret them correctly.", "Không coi notch và drill hole là chi tiết phụ. Chúng phải được kiểm soát như một phần của dữ liệu rập và quy trình cắt.": "Do not treat notches and drill holes as minor details. They must be controlled as part of the pattern data and cutting process.", "Đối chiếu vị trí notch, drill hole và dấu bấm với rập chuẩn; kiểm tra độ sâu, hướng và khả năng nhận biết sau bóc kiện mà không làm suy yếu chi tiết.": "Compare notch, drill-hole and punch-mark positions with the master pattern. Check depth, orientation and visibility after bundling, while ensuring that the marks do not weaken the component.", "Numbering là quá trình đánh số hoặc mã hóa các chi tiết sau cắt để giữ quan hệ giữa từng chi tiết, lớp vải, lay và cuộn. Khi kết hợp shade control, numbering giúp bảo đảm các chi tiết của cùng một sản phẩm được phối từ nhóm màu tương thích và không bị trộn lẫn trong quá trình bó kiện.": "Numbering assigns a number or code to cut components so that each component remains linked to its fabric ply, lay and roll. Combined with shade control, numbering helps ensure that all components for one garment come from compatible colour groups and are not mixed during bundling.", "Phương pháp đánh số cần phù hợp với loại vải và yêu cầu ngoại quan. Có thể dùng ticket, nhãn, mã in hoặc hệ thống điện tử; vị trí đánh dấu không được làm bẩn, thủng hoặc để lại vết trên vùng thành phẩm. Dữ liệu phải đủ để truy ngược style, màu, size, lay, lớp, roll ID và shade group. Nếu một lay có nhiều cuộn, điểm chuyển cuộn phải được ghi rõ.": "The numbering method must suit the fabric and appearance requirements. Tickets, labels, printed codes or electronic systems may be used, but the marking position must not soil, perforate or leave a trace on a finished area. The data must support traceability by style, colour, size, lay, ply, roll ID and shade group. If a lay contains multiple rolls, each roll-change point must be recorded.", "Sau cắt, đánh số theo trình tự đã quy định, đối chiếu chi tiết trái/phải và chi tiết đối xứng. Khi phối bundle, kiểm tra các chi tiết thuộc cùng số bộ và cùng shade group. Nếu thiếu hoặc hỏng ticket, phải tái lập theo hồ sơ lay; không tự ghép chi tiết cùng size từ bó khác khi chưa xác minh lot/shade.": "After cutting, number components in the prescribed sequence and verify left/right and symmetrical components. During bundling, confirm that components belong to the same set number and shade group. If a ticket is missing or damaged, reconstruct it from the lay record. Do not take a same-size component from another bundle until its lot and shade have been verified.", "Ví dụ: thân trước, thân sau và tay của một áo được lấy từ ba vị trí khác nhau trong lay. Nếu numbering không liên kết được với lớp và roll, bộ phận bó kiện có thể ghép các chi tiết có shade khác nhau. Mã bundle cần giữ thông tin tối thiểu để truy xuất cả ba nhóm chi tiết về lay và nguồn vải.": "For example, the front, back and sleeve components of a garment may come from three different positions in a lay. If numbering does not link them to their plies and rolls, bundling staff may combine components with different shades. The bundle code must retain enough information to trace all three component groups back to the lay and fabric source.", "Biểu mẫu kiểm numbering nên có số lượng chi tiết theo mã, số ticket phát hành, số bundle hoàn tất, số thiếu/hỏng, shade group và người xác nhận. Có thể đối chiếu tổng số chi tiết cắt với số lượng bundle để phát hiện thiếu trước khi chuyển may.": "The numbering control form should record component quantities by code, tickets issued, bundles completed, missing or damaged tickets, shade group and the person confirming the check. Compare the total cut-component quantity with the bundle count to identify shortages before transfer to sewing.", "Không chỉ kiểm số thứ tự có liên tục hay không. Cần kiểm tính đúng của quan hệ giữa mã số, lớp vải, chi tiết và shade group.": "Do not check only whether the sequence is continuous. Verify that each code correctly links the component to its fabric ply and shade group.", "Đảm bảo số thứ tự chi tiết liên kết với cây vải, lay, size và shade; thử truy ngược một bundle để xác nhận không mất dấu khi tách bó.": "Ensure that component numbering links to the fabric roll, lay, size and shade. Trace a sample bundle backwards to confirm that traceability is retained when bundles are split.", "Bundling là quá trình gom các chi tiết đã cắt thành bộ hoặc bó theo quy tắc cấp phát cho chuyền may. Bundle ticket là chứng từ nhận diện bó, giúp người vận hành biết mã hàng, màu, cỡ, số lượng, công đoạn hoặc thứ tự cấp phát. Phối kiện đúng giảm thời gian tìm kiếm và ngăn trộn lẫn chi tiết.": "Bundling groups cut components into sets or bundles according to the issue rules for the sewing line. A bundle ticket identifies the bundle and tells operators its style, colour, size, quantity, operation or issue sequence. Correct bundle assembly reduces searching time and prevents components from being mixed.", "Quy tắc bó phụ thuộc cấu trúc sản phẩm và phương thức sản xuất. Một bó có thể chứa đủ chi tiết cho một số sản phẩm hoặc chỉ một nhóm chi tiết cho một operation. Ticket cần nêu rõ bundle ID, style, màu, size, số lượng, lay/roll/shade nếu cần, mã chi tiết và tuyến cấp phát. Mã vạch hoặc QR chỉ hữu ích khi dữ liệu phía sau được duy trì chính xác.": "Bundling rules depend on product construction and the production method. A bundle may contain all components for several garments or only one component group for a particular operation. The ticket should state the bundle ID, style, colour, size, quantity, lay/roll/shade where required, component code and issue route. A barcode or QR code is useful only when its underlying data is maintained accurately.", "Khi bó, kiểm số lượng từng loại chi tiết, ghép cặp trái/phải, giữ đúng shade group và đảm bảo ticket không bị tách khỏi bó. Nếu bó được chia nhỏ cho nhiều vị trí, mỗi phần cần có mã con hoặc quy tắc truy vết. Khi phát hiện thiếu, ghi thiếu ở đúng mã chi tiết và lay để cutting có thể điều tra.": "During bundling, count each component type, pair left and right components, maintain the correct shade group and keep the ticket attached to the bundle. If a bundle is split for different workstations, each portion needs a sub-code or a defined traceability rule. Record any shortage against the exact component code and lay so that the cutting department can investigate.", "Ví dụ: bundle 015 có 20 bộ thân áo nhưng thiếu 2 tay trái. Không ghi chung “thiếu 2 chi tiết”; ticket hoặc phiếu sai lệch phải ghi mã chi tiết, size, số lớp/lay và trạng thái bù. Chuyền may không nên lấy tay từ bundle khác chỉ để đủ số lượng nếu chưa xác nhận shade và phiên bản rập.": "For example, bundle 015 contains 20 body sets but is short two left sleeves. Do not record this simply as 'two components missing'. The ticket or discrepancy report must state the component code, size, ply/lay and replacement status. The sewing line should not take sleeves from another bundle merely to complete the quantity until shade and pattern revision have been verified.", "Phiếu bàn giao cần ghi số bundle, số chi tiết theo mã, tổng số sản phẩm tương đương, tình trạng ticket, lỗi/thiếu và chữ ký hai bên. Người nhận xác nhận cả số lượng lẫn tình trạng vật lý của bó.": "The handover sheet should record the bundle number, component quantities by code, equivalent garment quantity, ticket status, defects or shortages and both parties' signatures. The recipient must confirm both the quantity and the physical condition of each bundle.", "Bó quá lớn có thể khó thao tác và làm tăng thời gian tìm chi tiết; bó quá nhỏ làm tăng số lần cấp phát. Kích thước bó cần thử theo layout, phương thức sản xuất và năng lực người vận hành.": "An oversized bundle can be difficult to handle and may increase the time needed to find components; undersized bundles increase the number of material-issue transactions. Bundle size should be trialled against the layout, production method and operator capacity.", "Ticket phải chỉ rõ style, PO, màu, size, bundle, số lượng và shade; đối chiếu số chi tiết theo bộ trước khi bàn giao để tránh thiếu hoặc trộn size.": "The ticket must identify the style, PO, colour, size, bundle, quantity and shade. Reconcile component quantities by set before handover to prevent shortages or size mixing.", "Fusing liên kết interlining với vải nền bằng tổ hợp nhiệt, áp lực và thời gian tiếp xúc. Chất lượng liên kết phụ thuộc loại keo, cấu trúc dựng, nền vải, lớp hoàn tất, độ ẩm, trạng thái bề mặt và cấu hình máy ép. Một bộ thông số chỉ có giá trị với tổ hợp vật liệu và thiết bị đã được thử nghiệm, không nên chuyển nguyên xi sang mã vải khác.": "Fusing bonds interlining to the shell fabric through a combination of heat, pressure and dwell time. Bond quality depends on the adhesive type, interlining construction, shell fabric, finish, moisture, surface condition and press configuration. A parameter set is valid only for the material and equipment combination on which it was tested; it should not be transferred unchanged to another fabric code.", "Trước ép, xác nhận mặt keo, hướng đặt, mã dựng, lot vật liệu và yêu cầu của chi tiết. Kiểm tra máy ép đạt trạng thái vận hành, bề mặt băng tải/bàn ép sạch và hệ thống đo nhiệt/áp lực được kiểm tra theo quy trình bảo trì. Nhiệt độ hiển thị không nhất thiết bằng nhiệt độ thực tế tại bề mặt tiếp xúc; vì vậy cần dùng phương pháp xác nhận phù hợp của nhà máy và nhà cung cấp.": "Before pressing, confirm the adhesive side, placement direction, interlining code, material lot and component requirements. Check that the fusing press is operational, the conveyor or press surface is clean, and temperature and pressure measurement systems have been checked under the maintenance procedure. The displayed temperature may differ from the actual temperature at the bonding interface, so use a verification method agreed by the factory and supplier.", "Thử nghiệm cần đánh giá bond strength, strike-through, bubbling, delamination, shrinkage, shade change, hand feel và độ ổn định sau thời gian nguội. Nếu sản phẩm có giặt/ủi hoặc xử lý hoàn tất, mẫu thử cần đi qua quy trình đại diện. Ghi đầy đủ máy, băng tải, nhiệt độ, áp lực, thời gian, tốc độ, lot keo và vải để có thể tái lập.": "Trials should assess bond strength, strike-through, bubbling, delamination, shrinkage, shade change, hand feel and stability after cooling. If the product will be washed, pressed or otherwise finished, the test sample should undergo a representative process sequence. Record the machine, conveyor, temperature, pressure, dwell time, speed, adhesive lot and fabric lot so that the result can be reproduced.", "Ví dụ: một loại dựng bám tốt ngay sau ép nhưng bong mép sau giặt. Nếu chỉ kiểm tra ngay tại máy, lỗi sẽ bị bỏ sót. Kế hoạch thử cần xác định thời gian ổn định và phương pháp giặt/ủi phù hợp với yêu cầu sản phẩm. Mẫu đạt phải được lưu cùng thông số được duyệt.": "For example, an interlining may bond well immediately after pressing but peel at the edge after washing. An inspection performed only at the press would miss the defect. The test plan should define the stabilisation period and a washing or pressing method appropriate to the product requirements. Retain an approved sample together with the approved settings.", "Khi có bubbling hoặc strike-through, không chỉ tăng nhiệt hoặc áp lực. Cần xem xét độ ẩm, tương thích keo-vải, lượng keo, tốc độ băng tải, độ sạch bề mặt và điều kiện bảo quản. Thay đổi từng biến có kiểm soát để xác định nguyên nhân.": "When bubbling or strike-through occurs, do not simply increase temperature or pressure. Review moisture, adhesive-to-fabric compatibility, adhesive quantity, conveyor speed, surface cleanliness and storage conditions. Change one variable at a time under controlled conditions to identify the cause.", "Hồ sơ fusing gồm vật liệu, lot, máy, thông số đã duyệt, kết quả thử, mẫu chuẩn, người phê duyệt và ngày hiệu lực. Mỗi lần đổi lot hoặc nhà cung cấp cần đánh giá theo mức rủi ro.": "The fusing record should include the materials, lots, machine, approved parameters, trial results, reference sample, approver and effective date. A change of lot or supplier should trigger reassessment according to risk.", "Xác nhận đúng tổ hợp vải nền và interlining.": "Confirm the correct shell-fabric and interlining combination.", "Dùng thông số đã được thử nghiệm và phê duyệt.": "Use parameters that have been tested and approved.", "Kiểm sau thời gian ổn định và sau xử lý tiếp theo nếu có.": "Inspect after the stabilisation period and after any subsequent process, where applicable.", "Lưu lot vật liệu, máy và thông số để tái lập.": "Record material lots, machine and parameters so the process can be reproduced.", "Kiểm tra sau cắt xác nhận chi tiết có đúng hình dạng, kích thước, số lượng, hướng sợi, dấu kỹ thuật và tình trạng mép cắt trước khi chuyển sang bó kiện hoặc may. Đây là điểm chặn cuối để ngăn lỗi cắt lan vào chuyền, nơi việc sửa chữa thường tốn thời gian hơn và khó truy nguyên hơn.": "Post-cut inspection verifies component shape, dimensions, quantity, grain direction, technical marks and cut-edge condition before components move to bundling or sewing. It is the final control point for preventing cutting defects from reaching the sewing line, where correction is often more time-consuming and harder to trace.", "Kế hoạch kiểm tra cần phân biệt kiểm toàn bộ với kiểm lấy mẫu. Các chi tiết quan trọng về kích thước, đối xứng, vị trí notch hoặc ảnh hưởng đến độ vừa vặn có thể cần kiểm ở tần suất cao hơn. Dùng rập chuẩn, dưỡng hoặc thiết bị đo phù hợp; đặt chi tiết trên mặt phẳng, không kéo giãn để ép khớp. Với lay dày, kiểm lớp trên, giữa và dưới theo kế hoạch rủi ro.": "The inspection plan should distinguish between 100% inspection and sampling. Components critical to dimensions, symmetry, notch position or fit may require a higher inspection frequency. Use the master pattern, an appropriate template or measuring equipment. Place the component flat; do not stretch it to force alignment. For thick lays, inspect the top, middle and bottom plies according to the risk plan.", "Nhóm lỗi cần phân loại gồm sai kích thước/hình dạng, mép cắt xơ hoặc lệch, thiếu notch/drill, sai hướng, sai shade, thiếu chi tiết, lẫn size và hư hỏng bề mặt. Mỗi lỗi phải có quyết định: sửa được, cắt bù, cách ly hoặc chấp nhận có phê duyệt. Không tự sửa rập hoặc cắt lại khi chưa xác định nguyên nhân và phạm vi.": "Defects should be classified as incorrect dimensions or shape, frayed or misaligned cut edges, missing notches or drill holes, incorrect orientation, shade mismatch, missing components, size mixing or surface damage. Each defect requires a disposition: repair, recut, quarantine or accept with approval. Do not alter the pattern or recut before the cause and affected scope have been established.", "Ví dụ: chi tiết thân trước ở lớp giữa bị hụt 4 mm tại đường sườn. Kiểm tra cần xác định đây là sai số marker, lệch lay hay dao bị nghiêng; sau đó khoanh vùng các chi tiết cùng vị trí trong lay. Chỉ thay một chi tiết mà không kiểm các lớp còn lại có thể để lỗi tương tự tiếp tục đi vào chuyền.": "For example, a front-body component in a middle ply is 4 mm short at the side seam. The investigation should determine whether the cause is a marker error, lay displacement or blade deflection, then identify components cut at the same position throughout the lay. Replacing only the affected component without checking the other plies may allow the same defect to reach sewing.", "Phiếu kiểm sau cắt nên ghi lay, roll, layer range, mã chi tiết, điểm đo, kích thước chuẩn, kết quả thực tế, loại lỗi, số lượng ảnh hưởng và disposition. Dữ liệu này giúp tính tỷ lệ lỗi theo nguyên nhân thay vì chỉ báo tổng số lỗi.": "The post-cut inspection record should include the lay, roll, layer range, component code, measurement point, specification, actual result, defect type, affected quantity and disposition. This makes it possible to calculate defect rates by cause rather than reporting only a total defect count.", "Không dùng “đạt ngoại quan” thay cho kiểm kích thước và dấu kỹ thuật. Một chi tiết nhìn sạch vẫn có thể sai rập hoặc thiếu dấu lắp ráp.": "Do not use 'appearance acceptable' as a substitute for dimensional and technical-mark checks. A component may look clean while still having an incorrect pattern shape or missing assembly marks.", "Kiểm tra kích thước, notch, số lượng, shade và dấu lỗi trên mẫu đại diện; tách riêng chi tiết cần sửa và ghi rõ bundle chịu ảnh hưởng.": "Check dimensions, notches, quantity, shade and defect marks on representative samples. Segregate components requiring correction and identify the affected bundles.", "Định mức vải là lượng vật liệu dự kiến cần cho một đơn vị sản phẩm hoặc một nhóm sản phẩm theo điều kiện xác định. Định mức cần phân biệt phần tiêu hao lý thuyết từ marker với hao hụt vận hành như đầu/cuối lay, lỗi vải, nối cuộn, phần biên loại bỏ và cắt bù.": "Fabric consumption is the expected quantity of material required for one garment or a defined group of garments under specified conditions. The allowance must distinguish theoretical marker consumption from operational losses such as lay ends, fabric defects, roll joins, discarded selvedge and recutting.", "Một cách tính sơ bộ là lấy chiều dài marker nhân số lớp, sau đó quy đổi theo số sản phẩm tạo ra và bổ sung các khoản hao hụt được xác định bằng dữ liệu thực tế. Nếu marker có nhiều sản phẩm mỗi lớp, phải chia tổng chiều dài lay cho số sản phẩm tương ứng. Khi tính theo khối lượng, cần thêm khổ hữu dụng và GSM đã được xác nhận; không trộn đơn vị mét dài và kg nếu chưa quy đổi rõ.": "A preliminary calculation uses marker length multiplied by the number of plies, then converts the total into consumption per garment and adds losses established from actual data. If the marker contains multiple garments per ply, divide the total lay length by the corresponding garment quantity. For a mass-based calculation, use verified usable width and GSM. Do not mix linear metres and kilograms without an explicit conversion.", "Ví dụ minh họa: marker dài 8,2 m tạo 4 sản phẩm mỗi lớp. Tiêu hao chiều dài lý thuyết là 2,05 m/sản phẩm. Nếu thử nghiệm sản xuất ghi nhận thêm 3% hao hụt vận hành trên cơ sở được thống nhất, mức dự toán là 2,1115 m/sản phẩm. Con số 3% ở đây chỉ là giả định minh họa, không phải định mức tiêu chuẩn. Nhà máy phải thay bằng dữ liệu của vật liệu, style và phương pháp cắt thực tế.": "Illustrative example: an 8.2 m marker produces four garments per ply. The theoretical length consumption is 2.05 m per garment. If a production trial records an additional 3% operational loss on an agreed basis, the estimate becomes 2.1115 m per garment. The 3% figure is an illustrative assumption, not a standard allowance. The factory must replace it with data for the actual material, style and cutting method.", "Đối chiếu định mức cần dùng cùng một phạm vi: cùng size ratio, cùng usable width, cùng hướng trải và cùng quy tắc tính phần dư. Theo dõi lượng vải cấp, lượng thực dùng, tồn cuối, phế liệu phân loại và số lượng thành phẩm đạt. Nếu chênh lệch lớn, phân tích theo marker, roll, lay và nguyên nhân cụ thể.": "Consumption comparisons must use the same basis: the same size ratio, usable width, spreading direction and remnant-calculation rules. Track fabric issued, actual consumption, closing balance, classified waste and accepted output. If the variance is significant, analyse it by marker, roll, lay and specific cause.", "Bảng định mức nên có mã style, màu, size ratio, marker version, chiều dài marker, số sản phẩm/lớp, khổ hữu dụng, tiêu hao lý thuyết, hao hụt theo nhóm, định mức duyệt và ngày hiệu lực. Lưu cả giả định để người khác có thể tính lại.": "The consumption sheet should include style code, colour, size ratio, marker revision, marker length, garments per ply, usable width, theoretical consumption, loss by category, approved allowance and effective date. Retain the assumptions so that another person can reproduce the calculation.", "Không cộng một tỷ lệ hao hụt tùy ý vào mọi mã hàng. Tỷ lệ phải có cơ sở dữ liệu, phạm vi áp dụng và cơ chế cập nhật.": "Do not add an arbitrary loss percentage to every style. Each rate must have a data basis, a defined scope of application and an update mechanism.", "Tách tiêu hao marker, hao hụt đầu-cuối cây, lỗi vải, relaxation và phần dự phòng theo quy tắc costing; đối chiếu định mức với số liệu xuất kho thực tế.": "Separate marker consumption, roll-end losses, fabric defects, relaxation and contingency according to the costing rules. Compare the approved allowance with actual material-issue records.", "Cut order planning chuyển nhu cầu giao hàng thành các lệnh cắt có thể thực hiện, đồng thời cân bằng giữa thời hạn, năng lực phòng cắt, tồn nguyên liệu, lot/shade và yêu cầu cấp chuyền. Kế hoạch tốt phải cho biết cắt gì, số lượng bao nhiêu, khi nào, từ nguồn vải nào và ưu tiên bàn giao cho chuyền nào.": "Cut-order planning converts delivery demand into executable cutting orders while balancing deadlines, cutting-room capacity, material availability, lot and shade control, and sewing-line requirements. A workable plan states what will be cut, in what quantity and when, from which fabric source, and which sewing line has handover priority.", "Đầu vào gồm PO/đơn hàng đã xác nhận, kế hoạch giao, size ratio, tồn kho được giải phóng, trạng thái kiểm vải, marker plan, năng lực trải/cắt và thời gian chuyển bán thành phẩm. Planner cần phân nhóm theo style-color-lot, xác định số lay, số lớp và thứ tự chạy. Đơn hàng có vật liệu hạn chế hoặc shade phức tạp có thể cần ưu tiên kiểm/giải phóng trước khi lập lịch cắt.": "Inputs include confirmed POs, delivery plans, size ratios, released inventory, fabric-inspection status, marker plans, spreading and cutting capacity, and cut-component transfer time. The planner groups work by style, colour and lot, then determines the number of lays, ply counts and production sequence. Orders with constrained materials or complex shade requirements may need inspection and release priority before cutting is scheduled.", "Kế hoạch theo ngày/ca nên có cut order ID, style, color, size ratio, số lượng, marker version, lot, lay plan, thời gian dự kiến, máy/line cắt, trạng thái và mốc bàn giao. Cập nhật tiến độ theo các trạng thái: chờ nguyên liệu, chờ tài liệu, sẵn sàng cắt, đang trải, đang cắt, kiểm sau cắt, đang bó và đã bàn giao. Không đánh dấu hoàn tất chỉ vì máy đã cắt xong; số lượng đạt và hồ sơ bàn giao phải được xác nhận.": "The daily or shift plan should show the cut-order ID, style, colour, size ratio, quantity, marker revision, lot, lay plan, planned time, cutting machine or line, status and handover milestone. Update progress through defined states: awaiting material, awaiting documents, ready to cut, spreading, cutting, post-cut inspection, bundling and handed over. Do not mark an order complete merely because the machine has finished cutting; accepted quantity and handover records must also be confirmed.", "Ví dụ: chuyền may cần 400 bộ bán thành phẩm trước 14:00 ngày mai. Phòng cắt có hai lệnh khác cùng vật liệu. Planner cần tính thời gian kiểm vải, trải, cắt, numbering, QC và vận chuyển nội bộ; nếu chỉ xếp theo thứ tự nhận lệnh, có thể làm chậm chuyền đang chờ. Ưu tiên phải dựa trên nhu cầu chuyền và khả năng hoàn tất thực tế, không chỉ theo mức độ khẩn được ghi miệng.": "For example, a sewing line needs 400 cut-component sets by 14:00 tomorrow, while the cutting room has two other orders using the same material. The planner must account for fabric inspection, spreading, cutting, numbering, QC and internal transport. Scheduling only by order-receipt sequence may delay a line that is waiting for work. Priority should reflect line demand and realistic completion capacity, not merely a verbal claim of urgency.", "KPI tiến độ có thể gồm tỷ lệ cut order hoàn thành đúng hạn, số giờ chờ nguyên liệu/tài liệu, tỷ lệ thiếu chi tiết khi bàn giao và WIP giữa cutting-sewing. Định nghĩa mẫu số và thời điểm ghi nhận phải thống nhất.": "Progress KPIs may include the percentage of cut orders completed on time, hours lost waiting for materials or documents, the rate of component shortages at handover, and WIP between cutting and sewing. Denominators and recording cut-off times must be consistently defined.", "Khi thay đổi ưu tiên, lưu lý do và tác động đến các lệnh khác. Không liên tục chen lệnh mới mà không đánh giá năng lực vì sẽ làm tăng WIP và kéo dài thời gian hoàn thành tổng thể.": "When priorities change, record the reason and the impact on other orders. Repeatedly inserting new orders without checking capacity increases WIP and extends overall completion time.", "Lập lịch cắt theo ngày cần hàng của sewing, vật liệu sẵn sàng, năng lực máy và thời gian đổi màu; không phát hành cut order khi thiếu dữ liệu đầu vào.": "Schedule cutting against the sewing line's required date, material readiness, machine capacity and colour-change time. Do not release a cut order while required input data is missing.", "Hồ sơ bàn giao từ cutting sang sewing chứng minh bán thành phẩm đã được cắt, kiểm, đánh số và phối kiện theo đúng lệnh sản xuất. Đây là điểm chuyển trách nhiệm giữa hai bộ phận; thông tin không đầy đủ sẽ khiến chuyền may mất thời gian kiểm đếm, tìm kiếm hoặc phát hiện sai lệch quá muộn.": "The cutting-to-sewing handover record confirms that cut components have been cut, inspected, numbered and bundled against the correct production order. It marks the transfer of responsibility between the two departments. Incomplete information forces the sewing line to spend time recounting and searching, or causes discrepancies to be discovered too late.", "Bộ hồ sơ cần liên kết cut order, marker version, lay number, roll/lot/shade, số lượng theo size, bundle ID, kết quả kiểm sau cắt và danh sách sai lệch còn mở. Tùy quy mô nhà máy, dữ liệu có thể nằm trên phiếu giấy, hệ thống ERP/MES hoặc mã vạch. Dù dùng phương tiện nào, thông tin phải đọc được, có người lập và người nhận xác nhận.": "The handover pack should link the cut order, marker revision, lay number, roll/lot/shade, quantities by size, bundle IDs, post-cut inspection results and any outstanding discrepancies. Depending on factory scale, the data may be recorded on paper forms, in an ERP/MES system or through barcodes. Whatever the medium, the information must be legible and acknowledged by both the preparer and recipient.", "Trước bàn giao, cutting kiểm số lượng theo bundle, đối chiếu ticket, xác nhận các chi tiết đặc biệt, tách hàng chờ xử lý và bảo vệ bán thành phẩm khỏi bẩn/ẩm/biến dạng. Sewing kiểm số bó, mã hàng, màu, size, shade group, tình trạng bao gói và mức độ đầy đủ của chứng từ. Sai lệch được ghi trên cùng biên bản với người phụ trách và thời hạn xử lý.": "Before handover, cutting checks quantities by bundle, reconciles tickets, confirms special components, separates items awaiting disposition and protects cut components from dirt, moisture and distortion. Sewing checks the bundle count, style, colour, size, shade group, packaging condition and completeness of the documents. Record discrepancies on the same handover report, with an assigned owner and due date.", "Ví dụ: cut order ghi 500 sản phẩm, nhưng phiếu bàn giao có 498 bộ đạt và 2 bộ đang chờ cắt bù. Biên bản phải thể hiện rõ 498 bộ đã giao, 2 bộ còn mở, mã chi tiết thiếu và thời gian dự kiến bù. Ghi “đã giao 500” khi chưa đủ sẽ làm dữ liệu kế hoạch và trách nhiệm sai lệch.": "For example, a cut order calls for 500 garments, but the handover report contains 498 accepted sets and two sets awaiting recutting. The record must state clearly that 498 sets have been delivered, two remain open, identify the missing component code and give the expected replacement time. Recording '500 delivered' before the balance is complete would distort planning data and accountability.", "Biên bản bàn giao nên có thời gian, mã đơn, style/color/size, tổng số bundle, số lượng đạt, số lượng thiếu/chờ, shade/lot, lỗi ngoại quan, tình trạng ticket, vị trí lưu và chữ ký hai bên. Với đơn hàng lớn, có thể đính kèm bảng chi tiết theo bundle.": "The handover report should include the date and time, order code, style/colour/size, total bundles, accepted quantity, shortages or pending quantity, shade/lot, appearance defects, ticket status, storage location and both parties' signatures. For large orders, attach a bundle-level detail sheet.", "Không xem việc chuyển xe đẩy hoặc chuyển khu vực là hoàn tất bàn giao. Bàn giao chỉ hoàn thành khi hai bên xác nhận số lượng, nhận diện và tình trạng bán thành phẩm.": "Moving a trolley or transferring items to another area does not constitute completed handover. Handover is complete only when both departments confirm the quantity, identification and condition of the cut components.", "Bàn giao theo bundle với ticket, số lượng, size, shade, tình trạng QC và revision; hai bên xác nhận chênh lệch trước khi nhập WIP của chuyền.": "Hand over by bundle, with tickets, quantity, size, shade, QC status and revision. Both parties must acknowledge discrepancies before the components are entered into the sewing line's WIP.", "Lectra – Knowledge and resources về CAD, marker making và cắt tự động.": "Lectra – Knowledge and resources on CAD, marker making and automated cutting.", "Gerber Technology – giải pháp CAD, marker và automated cutting.": "Gerber Technology – CAD, marker-making and automated-cutting solutions.", "ASTM International – tra cứu phương pháp thử vật liệu dệt.": "ASTM International – consult test methods for textile materials.", "ISO – tra cứu tiêu chuẩn hiện hành theo phương pháp thử.": "ISO – consult current standards relevant to the test method.", "Lưu ý: Hệ thống 4-point, thời gian relaxation, dung sai cắt, định mức hao hụt và điều kiện fusing phải theo tiêu chuẩn nhà máy/khách hàng và tài liệu vật liệu. Không dùng một con số mặc định cho mọi loại vải.": "Note: The 4-Point System, relaxation time, cutting tolerances, loss allowances and fusing conditions must follow factory or customer standards and material documentation. Do not apply one default value to every fabric.", "Mỗi thứ một chút. Nhưng đều đáng dùng.": "A little of everything. All worth exploring.", "Thông số kỹ thuật cần đối chiếu với tech pack, tiêu chuẩn và yêu cầu đã duyệt của từng sản phẩm.": "Technical parameters must be checked against the tech pack, applicable standards and approved requirements for each product.", "Chính sách bảo mật": "Privacy Policy", "Điều khoản sử dụng": "Terms of Use", "Liên hệ": "Contact", "Về AppNho": "About AppNho", "Chuỗi cung ứng & thương mại": "Supply Chain & Trade", "Chuyển đổi số & dữ liệu": "Digital Transformation & Data", "Từ điển Anh – Việt – Trung": "English–Vietnamese–Chinese Dictionary", "AI": "AI", "Điều hướng AppNho": "AppNho navigation", "Điều hướng trong học viện": "Academy navigation", "Sáu nhóm kiến thức": "Six knowledge areas", "Ranh giới với công đoạn may": "Boundary with the sewing operation", "Sơ đồ quy trình cutting": "Cutting process diagram", "Tìm nội dung, thuật ngữ, lỗi cắt...": "Search topics, terminology and cutting defects...", "Giáo trình từ kiểm vải, shade, relaxation, trải vải, marker, máy cắt đến numbering, fusing, bundling và bàn giao chuyền may. Thông số công nghệ phải được xác nhận theo vật liệu, thiết bị và tiêu chuẩn khách hàng.": "This course covers fabric inspection, shade control, relaxation, spreading, markers, cutting equipment, numbering, fusing, bundling and handover to the sewing line. Process parameters must be verified against the material, equipment and customer standards.", "Phạm vi ở đây kết thúc tại việc chuẩn bị và bàn giao bán thành phẩm đạt yêu cầu: kiểm vải, relaxation, spreading, marker, cutting, numbering, bundling và fusing. Việc vận hành máy, bố trí chuyền và cân bằng công đoạn thuộc Phase 9 – quản lý chuyền may ; Phase 7 – máy móc ngành may . Giữ liên kết truy xuất giữa lot vải, sơ đồ cắt, bó hàng và lệnh sản xuất để tránh đứt thông tin khi bàn giao.": "This phase ends when conforming cut components have been prepared and handed over: fabric inspection, relaxation, spreading, marker preparation, cutting, numbering, bundling and fusing. Machine operation, line layout and operation balancing are covered in Phase 9 – Sewing Production Management and Phase 7 – Garment Machinery. Maintain traceability links among fabric lots, cutting markers, bundles and production orders so that information is not lost at handover.", "Chuẩn bị sản xuất là quá trình chuyển yêu cầu của đơn hàng thành một hệ thống dữ liệu, vật liệu và bán thành phẩm đủ điều kiện để chuyền may vận hành. Chất lượng của công đoạn này được quyết định bởi tính nhất quán giữa tech pack, rập, BOM, cut order, marker, lot nguyên liệu và kế hoạch giao hàng.": "Pre-production converts order requirements into a controlled set of data, materials and cut components that are ready for the sewing line. Its quality depends on consistency among the tech pack, patterns, BOM, cut order, marker, material lots and delivery plan.", "Không nên xem cutting là một công đoạn độc lập. Một thay đổi về thông số thành phẩm có thể làm thay đổi rập; thay đổi rập kéo theo marker; thay đổi size ratio tác động đến cut order và số lớp; thay đổi lot hoặc shade có thể buộc tách lay. Vì vậy, mọi tài liệu phát hành phải có mã hàng, phiên bản, ngày hiệu lực và người phê duyệt. Bộ phận chuẩn bị sản xuất cần có một điểm kiểm soát thay đổi để ngăn bản cũ tiếp tục được sử dụng ở hiện trường.": "Cutting should not be treated as an isolated operation. A change to finished-garment measurements may require a pattern change; a pattern change affects the marker; a change in size ratio affects the cut order and ply count; and a change in lot or shade may require the lay to be split. Every released document must therefore carry a style code, revision, effective date and approver. Pre-production needs a formal change-control point to prevent superseded documents from remaining in use on the shop floor.", "Luồng kiểm soát nên đi theo thứ tự: xác nhận đơn hàng và tài liệu kỹ thuật; kiểm tra tình trạng nguyên liệu; xác nhận khổ hữu dụng, shade và độ co; phát hành rập/marker; lập cut order và lay plan; trải, cắt, đánh số, phối kiện; kiểm tra số lượng và bàn giao. Ở mỗi bước cần xác định đầu vào, đầu ra, người chịu trách nhiệm và điều kiện dừng. Không chuyển sang bước sau khi dữ liệu cốt lõi còn mâu thuẫn.": "The control sequence should be: confirm the order and technical documents; inspect material status; verify usable width, shade and shrinkage; release patterns and markers; prepare the cut order and lay plan; spread, cut, number and bundle; then verify quantities and hand over. Each step needs defined inputs, outputs, ownership and stop conditions. Do not proceed while core data remain inconsistent.", "Ví dụ: đơn hàng 1.200 áo có ba màu và năm cỡ. Nếu một màu được giao từ hai lot nhuộm có shade khác nhau, kế hoạch cắt phải tách lot hoặc có phê duyệt phối màu cụ thể. Không thể chỉ lấy tổng số lượng 1.200 để lập một lay duy nhất. Cut order phải phân bổ số lượng theo màu, cỡ và lot; phiếu bó sau cắt phải giữ được liên kết đó.": "For example, an order for 1,200 shirts has three colours and five sizes. If one colour is supplied from two dye lots with different shades, the cutting plan must separate the lots or obtain specific approval for colour mixing. The total quantity of 1,200 cannot simply be treated as one lay. The cut order must allocate quantities by colour, size and lot, and the post-cut bundle ticket must preserve those links.", "Bộ hồ sơ tối thiểu gồm tech pack phiên bản hiệu lực, bảng thông số, BOM, pattern/marker release, phiếu kiểm vải, cut order, lay plan, báo cáo cắt, bundle ticket và biên bản bàn giao. Khi phát sinh thiếu chi tiết, truy ngược theo mã lay, cuộn vải, phiên bản rập và ca cắt thay vì chỉ ghi nhận thiếu hụt tổng.": "The minimum record set includes the current tech pack, measurement specification, BOM, pattern/marker release, fabric-inspection report, cut order, lay plan, cutting report, bundle tickets and handover record. When a component shortage occurs, trace it by lay ID, fabric roll, pattern revision and cutting shift rather than recording only an overall shortage.", "Rủi ro thường gặp là tài liệu không đồng phiên bản, nguyên liệu chưa được giải phóng, thay đổi size ratio không cập nhật, hoặc số lượng cắt thực tế không đối chiếu với cut order. Một bảng theo dõi trạng thái đơn giản có thể dùng các cột: mã đơn, màu/size, tài liệu đã duyệt, nguyên liệu đã kiểm, marker đã phát hành, số lượng kế hoạch, số lượng cắt đạt, số lượng chờ xử lý và người xác nhận.": "Common risks include documents at different revisions, materials that have not been released, size-ratio changes that have not been updated, and actual cut quantities that are not reconciled with the cut order. A simple order-status tracker can include order code, colour/size, approved documents, inspected materials, released marker, planned quantity, accepted cut quantity, quantity on hold and the person confirming the status.", "Trước khi mở lệnh cắt, xác nhận revision rập-marker, cut order, size ratio, shade plan và tình trạng vật liệu; mọi sai khác phải có người chốt trước khi trải.": "Before releasing a cutting order, confirm the pattern and marker revisions, cut order, size ratio, shade plan and material status. An authorised person must resolve every discrepancy before spreading begins.", "Kiểm tra vải đầu vào phải xác nhận đúng vật liệu được đặt mua và đánh giá khả năng sử dụng của từng cuộn trước khi đưa vào lay. Tên thương mại hoặc mã màu trên nhãn chưa đủ để kết luận cuộn vải phù hợp; cần đối chiếu PO, packing list, tiêu chuẩn vật liệu và yêu cầu riêng của đơn hàng.": "Incoming fabric inspection confirms that the delivered material matches the purchase requirements and assesses whether each roll is suitable for use in a lay. A trade name or colour code on the label is not enough to establish conformity. Check it against the PO, packing list, material specification and order-specific requirements.", "Các thuộc tính cần kiểm tra tùy mặt hàng gồm mã vải, thành phần xơ, kiểu cấu trúc, màu, lot nhuộm, khổ danh nghĩa, khổ hữu dụng, trọng lượng, chiều dài, độ co, độ lệch màu và lỗi bề mặt. Với vải có tuyết, sọc, caro hoặc hoa văn định hướng, cần kiểm tra thêm hướng nap, repeat và khả năng phối họa tiết. Chỉ đo những chỉ tiêu có phương pháp và dung sai được quy định; không tự thay thế tiêu chuẩn khách hàng bằng giới hạn nội bộ chưa được phê duyệt.": "Depending on the product, inspection attributes may include fabric code, fibre composition, construction, colour, dye lot, nominal width, usable width, weight, length, shrinkage, colour variation and surface defects. For pile fabrics, stripes, checks or directional prints, also check nap direction, pattern repeat and matching requirements. Measure only attributes for which a method and tolerance have been specified; do not replace a customer standard with an unapproved internal limit.", "Quy trình kiểm tra nên bắt đầu bằng đối chiếu nhãn cuộn với chứng từ, sau đó kiểm ngoại quan trên máy kiểm vải hoặc bàn kiểm đủ ánh sáng. Ghi lỗi theo mã lỗi thống nhất, chiều dài cuộn và vị trí ngang khổ; đo khổ tại nhiều vị trí theo kế hoạch lấy mẫu; kiểm tra độ co trên mẫu đại diện nếu tiêu chuẩn yêu cầu. Cuộn chưa rõ lot, thiếu nhãn hoặc có sai lệch chứng từ phải được cách ly, không đưa vào khu vực cấp phát.": "Inspection should begin by matching the roll label to the accompanying documents, followed by a visual examination on a fabric-inspection machine or a properly illuminated inspection table. Record defects using standard defect codes, roll length and cross-width position. Measure width at multiple locations under the sampling plan, and test shrinkage on a representative sample when required by the specification. Quarantine rolls with an unclear lot identity, missing labels or document discrepancies; do not move them into the issuing area.", "Ví dụ phiếu kiểm cuộn có thể ghi: roll ID, supplier lot, màu, khổ đo, chiều dài nhãn, chiều dài thực đo, lỗi lớn nhất, vị trí lỗi, điểm kiểm theo hệ thống áp dụng và quyết định. Nếu nhãn ghi 150 cm nhưng khổ hữu dụng đo được chỉ 146 cm, marker thiết kế cho 148 cm không được phát hành cho cuộn đó trước khi kỹ thuật xác nhận phương án.": "A roll-inspection record may include roll ID, supplier lot, colour, measured width, labelled length, actual measured length, largest defect, defect location, inspection score under the applicable system and disposition. If the label states 150 cm but measured usable width is only 146 cm, a marker designed for 148 cm must not be released for that roll until engineering has confirmed the solution.", "Kết quả kiểm tra phải dẫn đến một trạng thái rõ ràng: đạt, đạt có điều kiện, chờ đánh giá hoặc không đạt. “Đạt có điều kiện” cần nêu điều kiện sử dụng, chẳng hạn chỉ dùng cho chi tiết nhỏ hoặc phải tách riêng. Dữ liệu cuộn phải liên kết với lay và bundle để khi phát hiện lỗi sau cắt có thể khoanh vùng chính xác.": "Inspection must result in a clear status: accepted, conditionally accepted, pending evaluation or rejected. Conditional acceptance must state the permitted use, such as use only for small components or mandatory segregation. Roll data must remain linked to the lay and bundle so that a defect found after cutting can be traced to its exact scope.", "Lỗi quản lý phổ biến là kiểm một vài cuộn rồi mặc định toàn bộ lô giống nhau, bỏ qua khổ hữu dụng, hoặc ghi lỗi mà không định vị. Kiểm tra đầu vào không thay thế việc kiểm soát trong trải và sau cắt; nó tạo dữ liệu nền để quyết định sử dụng vật liệu và giảm rủi ro đưa lỗi vào sản xuất.": "Common control failures include inspecting only a few rolls and assuming the entire lot is identical, overlooking usable width, or recording a defect without locating it. Incoming inspection does not replace controls during spreading and after cutting; it provides the baseline data for material-use decisions and reduces the risk of defects entering production.", "Lấy mẫu theo cây và theo lô, ghi khổ hữu dụng, lỗi bề mặt, chiều dài, shade và tình trạng biên; cách ly cây chưa có quyết định QC.": "Sample by roll and lot. Record usable width, surface defects, length, shade and selvedge condition. Quarantine any roll that has not received a QC disposition.", "Hệ thống 4-point là một phương pháp chấm điểm lỗi vải được sử dụng trong một số chương trình kiểm tra, trong đó điểm được gán theo quy tắc kích thước hoặc mức độ lỗi. Kết quả chỉ có ý nghĩa khi người kiểm tra sử dụng đúng phiên bản tiêu chuẩn, đúng đơn vị đo và đúng quy tắc cộng điểm của khách hàng hoặc nhà máy.": "The 4-Point System is a fabric-defect scoring method used in some inspection programmes. Points are assigned according to defined defect dimensions or severity. The result is meaningful only when inspectors use the correct standard revision, units of measurement and customer- or factory-specific scoring rules.", "Không nên học thuộc một bảng điểm rời rạc rồi áp dụng cho mọi đơn hàng. Các tiêu chuẩn có thể khác nhau về cách phân loại lỗi, giới hạn điểm cho một lỗi, cách xử lý lỗi liên tục, đơn vị diện tích/chiều dài và ngưỡng chấp nhận. Trước khi kiểm, trưởng nhóm phải xác nhận tài liệu đang hiệu lực, cách quy đổi và yêu cầu lấy mẫu. Nếu tiêu chuẩn không nêu rõ một tình huống, cần xin quyết định kỹ thuật thay vì tự suy diễn.": "Do not memorise an isolated scoring table and apply it to every order. Standards may differ in defect classification, the maximum points assigned to one defect, treatment of continuous defects, area or length units, and acceptance thresholds. Before inspection, the team leader must confirm the current document, conversion rules and sampling requirements. If the standard does not address a situation, obtain an engineering decision rather than making an assumption.", "Người kiểm cần nhận diện lỗi, xác định chiều dài hoặc kích thước theo phương pháp quy định, ghi vị trí theo chiều dài cuộn và ngang khổ, sau đó gán điểm. Báo cáo phải giữ được cả dữ liệu gốc và kết quả tổng hợp. Với lỗi có tính lặp như sọc, barré hoặc lệch màu, ngoài điểm số cần mô tả phạm vi và tính liên tục vì ảnh hưởng đến khả năng bố trí chi tiết có thể lớn hơn điểm tổng.": "The inspector identifies each defect, measures its length or dimensions using the specified method, records its position along the roll and across the width, and then assigns the score. The report must retain both the raw observations and the calculated result. For recurring defects such as stripes, barré or colour variation, record the extent and continuity as well as the score, because their effect on component placement may be more significant than the total score suggests.", "Ví dụ minh họa: một cuộn được kiểm 50 m và có ba lỗi tại các vị trí 8 m, 21 m và 43 m. Nhật ký phải ghi riêng loại lỗi, kích thước, tọa độ và điểm theo tiêu chuẩn áp dụng; không chỉ ghi “tổng 6 điểm”. Khi bộ phận cắt phát hiện một chi tiết nằm đúng vùng lỗi, dữ liệu tọa độ cho phép truy lại cuộn và đánh giá các lay khác đã dùng cùng cuộn.": "Illustrative example: a 50 m roll has three defects at 8 m, 21 m and 43 m. The log should record each defect type, dimension, coordinate and score under the applicable standard; it should not merely state 'six points total'. If cutting later finds a component in one of these defect zones, the coordinates make it possible to trace the roll and assess other lays that used it.", "Phiếu kiểm nên có roll ID, mã vải, lot, tổng chiều dài kiểm, số lỗi theo nhóm, điểm quy đổi, tiêu chuẩn/phiên bản, kết luận và chữ ký người kiểm. Nếu tính điểm trên một đơn vị chiều dài hoặc diện tích, phải ghi rõ mẫu số và cách xử lý phần không kiểm.": "The inspection sheet should include roll ID, fabric code, lot, total length inspected, defect count by category, calculated score, standard and revision, disposition and inspector's signature. If the score is calculated per unit of length or area, state the denominator and how uninspected portions are treated.", "Điểm lỗi thấp không đồng nghĩa mọi vị trí đều có thể sử dụng. Một lỗi nhỏ nhưng nằm ở vùng mặt trước dễ thấy hoặc ảnh hưởng đến chi tiết đối xứng có thể cần loại trừ. Kết luận sử dụng phải kết hợp điểm số, vị trí lỗi, yêu cầu ngoại quan và quyết định của người có thẩm quyền.": "A low defect score does not mean that every part of the roll is usable. A small defect in a highly visible front area or on a symmetrical component may still need to be excluded. The use decision must consider the score, defect location, appearance requirements and approval by an authorised person.", "Xác nhận tiêu chuẩn và phiên bản áp dụng.": "Confirm the applicable standard and revision.", "Ghi từng lỗi cùng kích thước và vị trí trên cuộn.": "Record each defect with its dimensions and position on the roll.", "Giữ dữ liệu gốc trước khi tính điểm tổng.": "Retain the raw inspection data before calculating the total score.", "Đánh giá khả năng sử dụng theo vị trí lỗi, không chỉ điểm tổng.": "Assess usability by defect location, not by the total score alone.", "Shade band là cách phân nhóm vải theo mức độ tương đồng màu để hạn chế khác biệt màu giữa các chi tiết của cùng sản phẩm. Trong sản xuất may, kiểm soát shade cần thực hiện từ khâu nhận vải, kiểm màu, lập kế hoạch cắt đến đánh số và phối kiện; nếu chỉ kiểm màu ở đầu vào mà không giữ thông tin lot đến bundle, khả năng truy xuất sẽ bị mất.": "Shade banding groups fabric by colour similarity to limit visible colour differences among components of the same garment. In garment production, shade control must extend from fabric receipt and colour inspection through cutting plans, numbering and bundling. If lot information is checked at receipt but not retained through to the bundle, traceability is lost.", "Màu có thể biến thiên giữa lot nhuộm, giữa đầu và cuối cuộn, giữa hai biên và giữa các vị trí theo chiều dài. Với vải có bề mặt định hướng, góc nhìn và hướng đặt cũng làm cảm nhận màu thay đổi. Vì vậy, quy trình đánh giá phải xác định nguồn sáng, góc quan sát, mẫu chuẩn, điều kiện ổn định mẫu và cách ghi kết quả. Dụng cụ đo màu có thể hỗ trợ so sánh nhưng không tự động thay thế đánh giá ngoại quan nếu tiêu chuẩn yêu cầu cả hai.": "Colour may vary between dye lots, from the beginning to the end of a roll, between the two selvedges and along the roll length. For fabrics with directional surfaces, viewing angle and component orientation can also change perceived colour. The assessment procedure must therefore define the light source, viewing angle, reference standard, sample-conditioning conditions and recording method. A colour-measuring instrument can support comparison, but it does not automatically replace visual assessment where the specification requires both.", "Mỗi cuộn cần được gắn mã lot và shade group sau khi đánh giá. Khi lập lay, hệ thống phải ngăn việc trộn các nhóm không tương thích, trừ khi có phê duyệt rõ ràng. Nếu một đơn hàng có nhiều shade band, cut order cần phân bổ số lượng theo từng nhóm; sau cắt, numbering phải giữ nguyên quan hệ giữa chi tiết và cuộn/lay để các chi tiết của cùng sản phẩm được phối đúng nhóm.": "After assessment, each roll must be assigned a lot code and shade group. The lay-planning system must prevent incompatible groups from being mixed unless explicit approval has been granted. If an order contains several shade bands, the cut order must allocate quantities by group. After cutting, numbering must preserve the link between each component and its roll/lay so that all components of one garment can be matched within the correct group.", "Ví dụ: thân trước và thân sau của một áo cùng size được cắt từ hai lay khác nhau. Nếu hai lay thuộc hai shade group, khi may có thể xuất hiện chênh màu ngay giữa thân trước và thân sau. Phiếu bundle vì vậy phải ghi shade group, lay number và roll range; bộ phận cấp phát không được gom bundle chỉ dựa vào cùng mã màu thương mại.": "For example, the front and back panels of the same size garment may be cut from two different lays. If the lays belong to different shade groups, a colour difference may appear between the front and back after sewing. The bundle ticket must therefore show the shade group, lay number and roll range. The issuing team must not combine bundles solely because they carry the same commercial colour code.", "Bảng theo dõi màu nên có mã màu chuẩn, lot nhà cung cấp, roll ID, shade group, kết quả so với mẫu chuẩn, quyết định sử dụng và phạm vi lay được phép. Khi thay mẫu chuẩn hoặc nguồn sáng đánh giá, phải lưu phiên bản và ngày áp dụng để tránh so sánh dữ liệu không tương đương.": "The colour-control register should include the standard colour code, supplier lot, roll ID, shade group, comparison result against the reference, use decision and permitted lay scope. If the reference sample or assessment light source changes, record its revision and effective date to avoid comparing non-equivalent results.", "Không dùng thuật ngữ “cùng màu” để thay cho “cùng shade”. Màu thương mại giống nhau chưa chắc đồng nhất về sắc độ. Cũng không tự đặt số lượng shade band tối đa hoặc dung sai ΔE nếu khách hàng chưa quy định; các ngưỡng này phải lấy từ tiêu chuẩn được duyệt.": "Do not use 'same colour' as a substitute for 'same shade'. Two rolls with the same commercial colour name may still differ in shade. Do not set a maximum number of shade bands or a ΔE tolerance unless the customer has specified it; such limits must come from an approved standard.", "Không trộn lot hoặc shade khi chưa có quy tắc phối đã duyệt; đánh dấu đầu cây, hướng màu và nhóm shade trên ticket để kiểm soát tới bundle.": "Do not mix lots or shades without an approved matching rule. Mark the roll start, colour direction and shade group on the ticket so control continues through to bundling.", "Relaxation là khoảng thời gian hoặc quy trình để vải trở về trạng thái ổn định hơn sau khi chịu lực kéo, cuộn chặt, vận chuyển hoặc lưu kho. Mục tiêu là hạn chế thay đổi kích thước sau cắt, đặc biệt với vật liệu có tính đàn hồi, cấu trúc dệt kim, vải pha elastane hoặc vải đã bị kéo căng trong quá trình cuộn và xử lý.": "Relaxation is a period or process that allows fabric to move towards a more stable state after being subjected to tension, tight winding, transport or storage. Its purpose is to limit dimensional change after cutting, particularly in elastic materials, knitted constructions, elastane blends or fabrics stretched during winding and handling.", "Thời gian relaxation không thể áp dụng như một con số cố định cho mọi loại vải. Mức độ hồi phục phụ thuộc cấu trúc, thành phần xơ, độ đàn hồi, độ ẩm, nhiệt độ, trạng thái cuộn và hướng dẫn của nhà cung cấp. Kỹ thuật cần xác định phương pháp trải nghỉ, chiều dài bàn, số lớp, cách phủ bảo vệ và thời gian chờ theo tiêu chuẩn vật liệu hoặc kết quả thử nghiệm. Với vật liệu có yêu cầu điều hòa nhiệt ẩm, điều kiện môi trường cần được ghi nhận.": "Relaxation time cannot be treated as one fixed value for every fabric. Recovery depends on construction, fibre content, elasticity, moisture, temperature, roll condition and supplier instructions. Engineering must define the relaxation-spreading method, table length, ply count, protective covering and waiting period according to the material specification or trial results. Where a material requires temperature and humidity conditioning, environmental conditions must also be recorded.", "Khi nhận vải, kiểm tra tình trạng cuộn và tránh kéo căng trong lúc tháo. Trải vải theo cách không tạo lực căng, để bề mặt phẳng và không chèn ép làm biến dạng. Sau thời gian ổn định, đo lại chiều dài/khổ hoặc kiểm tra thay đổi kích thước trên mẫu theo phương pháp được duyệt. Chỉ phát hành cắt khi kết quả nằm trong điều kiện quy định của mã hàng.": "On receipt, inspect the roll condition and avoid stretching the fabric during unrolling. Spread it without introducing tension, keeping the surface flat and avoiding pressure that could distort it. After the stabilisation period, remeasure length and width or assess dimensional change on a sample using the approved method. Release the fabric for cutting only when the result meets the conditions specified for the style.", "Ví dụ: một loại jersey có độ co hồi cao được trải ngay sau khi tháo khỏi cuộn có thể co ngắn theo chiều dài khi lực căng được giải phóng. Nếu marker được tính trên chiều dài chưa ổn định, số lượng chi tiết cuối lay hoặc kích thước chi tiết có thể sai. Cách xác minh là so sánh mẫu đo trước và sau relaxation trong cùng điều kiện, ghi rõ hướng đo và thời gian.": "For example, a highly elastic jersey spread immediately after unrolling may shorten along its length when the tension is released. If the marker is planned against an unstable length, the final components in the lay or their dimensions may be incorrect. Verify this by comparing measurements before and after relaxation under the same conditions, recording the measurement direction and elapsed time.", "Phiếu relaxation nên ghi mã vải, lot, roll ID, thời điểm tháo cuộn, thời điểm bắt đầu/kết thúc nghỉ, điều kiện môi trường nếu cần, phương pháp trải, kết quả đo và người xác nhận. Dữ liệu này cần gắn với lay number để khi có sai lệch kích thước sau may, nhà máy có thể phân tích nguyên nhân.": "The relaxation record should include fabric code, lot, roll ID, unrolling time, relaxation start and end times, environmental conditions where required, spreading method, measurement results and the person confirming the process. Link this data to the lay number so that the factory can investigate the cause of dimensional variation after sewing.", "Không nhầm relaxation với xử lý co trước (pre-shrinking) hoặc kiểm tra độ co. Relaxation giảm ảnh hưởng của trạng thái căng; pre-shrinking là quá trình xử lý vật liệu theo phương pháp cụ thể; thử độ co là phép đo phản ứng kích thước. Ba hoạt động có mục tiêu và phương pháp khác nhau.": "Do not confuse relaxation with pre-shrinking or shrinkage testing. Relaxation reduces the effects of a tensioned state; pre-shrinking is a material treatment carried out by a defined process; and shrinkage testing measures dimensional response. These activities have different purposes and methods.", "Ghi thời điểm mở kiện, điều kiện trải, thời gian relaxation theo hướng dẫn vật liệu và kết quả đo kích thước trước-sau; không dùng một thời gian chờ chung cho mọi loại vải.": "Record the unrolling time, spreading conditions, relaxation period specified for the material and before-and-after dimensional results. Do not apply one waiting time to every fabric type.", "Khổ danh nghĩa trên nhãn cuộn và khổ hữu dụng để bố trí rập là hai đại lượng khác nhau. Usable width là phần bề rộng thực tế có thể sử dụng sau khi loại trừ biên vải, vùng lỗi, vùng cong vênh hoặc phần không đáp ứng yêu cầu kỹ thuật của marker.": "The nominal width on a roll label and the usable width available for marker placement are two different measurements. Usable width is the actual width available after excluding selvedges, defect zones, distorted areas or other portions that do not meet the marker's technical requirements.", "Đo khổ tại nhiều vị trí dọc cuộn vì khổ có thể thay đổi theo chiều dài. Với vải dệt kim, mép cuộn có thể cuộn vào hoặc biến dạng; với vải dệt thoi, biên vải và độ cong khổ có thể ảnh hưởng đến phần bố trí. Cách đo phải quy định điểm đo, trạng thái vải, lực kéo và dụng cụ. Nếu kéo căng vải khi đo, kết quả có thể lớn hơn bề rộng sử dụng thực tế.": "Measure width at several positions along the roll because it may vary over its length. Knitted fabric edges may curl or distort; in woven fabric, selvedges and bowing can affect the available marker area. The method must define measurement points, fabric condition, applied tension and equipment. Stretching the fabric during measurement can produce a value greater than the width actually available for use.", "Kỹ thuật cần xác định usable width theo tiêu chuẩn: lấy khổ đo trừ phần biên không dùng và phần dự phòng do lỗi/độ cong nếu quy định yêu cầu. Sau đó cập nhật khổ thực tế vào hệ thống marker. Không sử dụng khổ rộng nhất của cuộn làm căn cứ cho toàn bộ cuộn nếu các điểm đo còn lại nhỏ hơn. Trường hợp khổ biến thiên vượt dung sai phải cách ly hoặc đánh giá lại marker.": "Engineering must determine usable width according to the applicable specification by subtracting unusable selvedges and any allowance for defects or bowing where required. Enter the verified width in the marker system. Do not use the widest measurement as the basis for the entire roll if other measurement points are narrower. If width variation exceeds the permitted tolerance, quarantine the roll or reassess the marker.", "Ví dụ minh họa: khổ đo tại ba vị trí lần lượt là 151, 150 và 148 cm; hai biên mỗi bên bị loại 1 cm theo quy định. Khổ hữu dụng tương ứng là 149, 148 và 146 cm. Marker rộng 147 cm chỉ có thể phù hợp ở các đoạn đạt ít nhất 147 cm; nếu không thể phân vùng lay, cần điều chỉnh marker hoặc xin phê duyệt phương án khác.": "Illustrative example: measured widths at three positions are 151, 150 and 148 cm. If 1 cm is excluded from each selvedge under the applicable rule, the corresponding usable widths are 149, 148 and 146 cm. A 147 cm marker is suitable only for sections with at least 147 cm of usable width. If the lay cannot be divided into suitable sections, revise the marker or obtain approval for an alternative plan.", "Báo cáo nên lưu khổ danh nghĩa, các điểm đo, usable width được chấp nhận, phương pháp đo, dung sai, roll ID và quyết định. Khi marker thay đổi khổ, phải phát hành phiên bản mới và xác nhận lại hiệu suất sơ đồ, số lượng chi tiết và mức tiêu hao.": "The report should retain nominal width, measurement points, accepted usable width, measurement method, tolerance, roll ID and disposition. If the marker width changes, issue a new revision and revalidate marker efficiency, component quantities and consumption.", "Lỗi thường gặp là dùng khổ danh nghĩa thay cho khổ hữu dụng, đo một điểm duy nhất, hoặc thay đổi khổ marker nhưng không kiểm tra lại toàn bộ chi tiết. Khổ hữu dụng là dữ liệu sản xuất có kiểm soát, không phải con số ước lượng.": "Common errors include using nominal width instead of usable width, measuring at only one point, or changing marker width without rechecking all components. Usable width is controlled production data, not an estimate.", "Đo usable width ở nhiều vị trí đại diện, loại trừ biên lỗi và vùng không dùng được trước khi lập marker; cập nhật định mức nếu khổ thực tế khác dữ liệu costing.": "Measure usable width at representative positions and exclude defective selvedges and unusable areas before marker planning. Update the consumption allowance if actual width differs from the costing data.", "Spreading là quá trình xếp các lớp vải thành lay theo chiều dài và chiều cao phù hợp với kế hoạch cắt. Lay phải đáp ứng đồng thời yêu cầu về số lớp, hướng mặt, hướng nap, shade, khổ, độ căng và độ thẳng mép. Chất lượng trải ảnh hưởng trực tiếp đến độ chính xác của chi tiết ở mọi lớp.": "Spreading is the process of laying fabric plies into a lay of the length and height required by the cutting plan. The lay must meet requirements for ply count, face orientation, nap direction, shade, width, tension and edge alignment. Spreading quality directly affects component accuracy on every ply.", "Trước khi trải, xác nhận cut order, marker, roll allocation, chiều dài lay, số lớp và cách đặt mặt vải. Kiểm tra bàn cắt sạch, phẳng, không có vật cản; xác định đầu lay và điểm chuẩn. Trong khi trải, kiểm soát lực căng, độ chồng mép, độ lệch biên, nếp nhăn và tình trạng mặt vải. Với vải có chiều, phải giữ đúng hướng; với vải có yêu cầu face-to-face hoặc one-way, tuân thủ sơ đồ đã phê duyệt.": "Before spreading, confirm the cut order, marker, roll allocation, lay length, ply count and fabric-face arrangement. Check that the cutting table is clean, level and free of obstructions, then identify the lay start and reference point. During spreading, control tension, ply overlap, edge alignment, wrinkles and fabric-face condition. Maintain the correct direction for directional fabrics and follow the approved lay arrangement for face-to-face or one-way spreading.", "Lay plan phải thể hiện mã lay, màu/size ratio, roll ID, shade group, số lớp, chiều dài marker và chiều dài lay thực tế. Nếu thay cuộn giữa lay, phải ghi điểm chuyển cuộn và bảo đảm cuộn thay thế tương thích về lot/shade. Không tự tăng số lớp vượt khả năng cắt của thiết bị hoặc làm giảm độ chính xác ở lớp dưới.": "The lay plan must show the lay ID, colour and size ratio, roll ID, shade group, ply count, marker length and actual lay length. If a roll is changed within a lay, record the change point and ensure that the replacement roll is compatible in lot and shade. Do not increase the ply count beyond the cutting equipment's capability or to a level that reduces accuracy on the lower plies.", "Ví dụ: cut order yêu cầu 240 sản phẩm với marker ratio 1:2:2 cho ba cỡ. Một lay 20 lớp tạo 20 bộ ratio, nhưng chỉ đúng khi mỗi lớp được trải cùng marker và số lớp không vượt giới hạn vật liệu/dao cắt. Nếu lay bị lệch mép 8 mm ở một đầu, chi tiết nằm sát biên có thể thiếu đường may hoặc sai hình dạng; cần dừng, căn chỉnh và ghi nhận phần lay đã bị ảnh hưởng.": "For example, a cut order requires 240 garments using a marker ratio of 1:2:2 across three sizes. A 20-ply lay produces 20 ratio sets, but only if every ply uses the same marker and the ply count remains within the limits of the material and cutting equipment. If the lay is displaced by 8 mm at one end, components near the edge may lose seam allowance or have the wrong shape. Stop, realign the lay and record the affected section.", "Kiểm tra đầu lay, giữa lay và cuối lay; đo chiều dài, chiều cao, độ lệch biên và xác nhận số lớp. Sau trải, người kiểm ký lay ticket trước khi cắt. Mọi sửa đổi số lớp hoặc roll allocation cần cập nhật hồ sơ trước khi vận hành.": "Inspect the beginning, middle and end of the lay. Measure its length and height, check edge displacement and confirm the ply count. After spreading, the inspector must sign the lay ticket before cutting. Any change to ply count or roll allocation must be entered in the records before operation.", "Không dùng tốc độ trải làm chỉ tiêu duy nhất. Trải nhanh nhưng tạo nếp, kéo giãn hoặc lệch lớp sẽ làm tăng phế liệu và lỗi kích thước. Hiệu quả phải được đánh giá cùng độ ổn định lay và tỷ lệ chi tiết đạt.": "Do not use spreading speed as the only performance measure. Fast spreading that creates wrinkles, stretching or ply misalignment increases waste and dimensional defects. Performance must be assessed together with lay stability and the acceptance rate of cut components.", "Xác nhận chiều trải, mặt vải, số lớp và cut order trước khi bắt đầu; kiểm tra mép lay và độ phẳng theo từng đoạn thay vì chỉ nhìn đầu bàn.": "Confirm spreading direction, fabric face, ply count and cut order before starting. Check lay edges and flatness along its length rather than inspecting only the table end.", "Trình tự triển khai": "Implementation Sequence", "Ví dụ áp dụng": "Worked Example", "Hồ sơ và điểm kiểm soát": "Records and Control Points", "Sai lệch cần phòng ngừa": "Deviations to Prevent", "☰": "☰", "Tất cả nhóm kiến thức": "All Knowledge Areas", "Chuẩn bị": "Preparation", "Máy cắt": "Cutting Machines", "Quản lý": "Management", "Sau cắt": "Post-cut", "Sơ đồ cắt": "Cutting Marker", "Trải vải": "Fabric Spreading", "One-way, face-to-face và nap direction là các quy tắc định hướng lớp vải khi trải. Chúng quyết định mặt nào tiếp xúc, chiều đặt chi tiết và khả năng xoay rập trên marker. Chọn sai quy tắc có thể làm màu hoặc bề mặt thay đổi giữa các chi tiết dù kích thước cắt vẫn đúng.": "One-way, face-to-face and nap direction are fabric-orientation rules used during spreading. They determine which fabric faces contact each other, the orientation of components and whether patterns may be rotated on the marker. An incorrect choice can cause colour or surface differences between components even when their cut dimensions are correct.", "Vải có nap như nhung, corduroy hoặc bề mặt chải thường thay đổi sắc độ theo hướng ánh sáng và hướng sợi. Vải in, sọc, caro hoặc họa tiết có chiều cũng có thể yêu cầu tất cả chi tiết cùng hướng. Face-to-face cho phép hai lớp đặt mặt phải đối diện nhau trong một số cấu hình, nhưng không mặc nhiên phù hợp với mọi vật liệu. One-way thường hạn chế xoay chi tiết 180 độ để duy trì hướng bề mặt hoặc họa tiết.": "Fabrics with a nap, such as velvet, corduroy or brushed surfaces, often change in appearance according to light and pile direction. Printed, striped, checked or directional-pattern fabrics may also require all components to face the same direction. Face-to-face spreading places the face sides of two plies together in certain configurations, but it is not automatically suitable for every material. One-way spreading generally restricts 180-degree component rotation to preserve surface or pattern direction.", "Quyết định hướng trải phải xuất phát từ mẫu duyệt, tiêu chuẩn vật liệu và thử nghiệm trên sản phẩm thực tế. Marker maker cần khóa hướng chi tiết và ghi chú rõ trong marker release. Người trải kiểm tra mũi tên nap, mặt phải, đầu lay và chiều đi của từng lớp. Khi đổi cách trải để tăng hiệu suất, phải may mẫu xác nhận dưới ánh sáng và điều kiện quan sát phù hợp.": "The spreading direction must be determined from the approved sample, material specification and trials on the actual product. The marker maker must lock component orientation and state it clearly in the marker release. The spreading operator checks the nap arrow, face side, lay start and direction of each ply. If the spreading method is changed to improve efficiency, sew a confirmation sample and assess it under suitable lighting and viewing conditions.", "Ví dụ: marker hai chiều có thể đạt hiệu suất cao hơn marker một chiều trên vải trơn. Nhưng nếu vải có nap, chi tiết đặt ngược hướng có thể nhìn tối/sáng khác nhau. Phần tiết kiệm vải trên sơ đồ không bù được rủi ro ngoại quan nếu khách hàng yêu cầu đồng hướng.": "For example, a two-way marker may achieve higher efficiency than a one-way marker on plain fabric. On a napped fabric, however, components placed in opposite directions may appear lighter or darker. The fabric saving shown by the marker does not offset the appearance risk when the customer requires a consistent direction.", "Phiếu lay cần ghi mã quy tắc trải, mặt vải hướng lên/xuống, chiều nap, cấu hình face-to-face hoặc one-way, số lớp và marker version. Kiểm tra ngẫu nhiên các chi tiết sau cắt để xác nhận mũi tên định hướng được giữ đúng.": "The lay ticket should record the spreading rule, whether the fabric face is up or down, nap direction, face-to-face or one-way configuration, ply count and marker revision. Randomly inspect cut components to confirm that the specified orientation has been maintained.", "Không suy luận quy tắc trải chỉ từ tên thành phần xơ. Hai loại vải cùng thành phần có thể có bề mặt và yêu cầu định hướng khác nhau. Mẫu thực tế và tiêu chuẩn đã duyệt mới là căn cứ quyết định.": "Do not infer the spreading rule from fibre composition alone. Two fabrics with the same fibre content may have different surfaces and orientation requirements. The actual approved sample and specification are the basis for the decision.", "Đối chiếu hướng lông, ánh màu, mặt phải và quy tắc một chiều trên marker; đánh dấu chiều trải để tránh chi tiết cùng sản phẩm có hiệu ứng bề mặt khác nhau.": "Compare pile direction, colour appearance, face side and one-way rules against the marker. Mark the spreading direction to prevent components of the same garment from showing different surface effects.", "Độ căng khi trải và sự thẳng hàng giữa các lớp quyết định mức độ ổn định của lay. Nếu vải bị kéo căng, lớp trên có thể co lại sau khi cắt; nếu các lớp lệch nhau, chi tiết ở lớp biên có thể thiếu vật liệu hoặc sai vị trí notch. Lay end là phần kết thúc lay cần được xử lý đúng theo sơ đồ và quy định cắt.": "Spreading tension and ply alignment determine lay stability. If the fabric is stretched, the upper plies may contract after cutting. If plies are misaligned, components near the edge may be short of material or have incorrectly positioned notches. The lay end must be prepared in accordance with the marker and cutting requirements.", "Lực kéo phải đủ để đưa vải phẳng nhưng không làm biến dạng cấu trúc. Với vải đàn hồi, kéo căng để xóa nếp là cách xử lý sai vì trạng thái này không còn tồn tại sau khi giải phóng lực. Ply alignment cần kiểm soát cả mép bên, đầu lay và chiều dài marker. Đối với vải có hoa văn, còn phải kiểm tra repeat và điểm khớp giữa các lớp.": "Applied tension should be sufficient to lay the fabric flat without distorting its structure. Stretching an elastic fabric to remove wrinkles is incorrect because the stretched condition will disappear when the tension is released. Ply alignment must be controlled at the side edges, lay start and marker length. For patterned fabrics, also check the repeat and matching points between plies.", "Trong quá trình trải, quan sát mép lớp ở nhiều vị trí, không chỉ tại đầu bàn. Đo sai lệch theo quy định và dừng khi vượt giới hạn đã được phê duyệt. Khi nối đầu cuộn, xử lý đoạn nối để không tạo lớp chồng bất thường hoặc thiếu chiều dài. Cuối lay phải đủ chiều dài marker và có phần dư theo yêu cầu; không kéo giãn lớp cuối để “đủ” chiều dài.": "During spreading, observe ply edges at multiple positions, not only at the table start. Measure displacement as specified and stop when it exceeds the approved limit. When joining roll ends, manage the joint so that it does not create abnormal overlap or insufficient length. The lay end must cover the marker length and any required allowance; do not stretch the final ply to make up the length.", "Ví dụ: marker dài 8,4 m nhưng lay chỉ được trải 8,32 m. Nếu người vận hành kéo căng thêm 8 cm để khớp marker, sau khi vải hồi phục, chi tiết cuối có thể thiếu chiều dài. Cách đúng là kiểm tra điểm chuẩn, chiều dài thực, đầu cuộn và marker version; nếu thiếu phải lập lại lay hoặc điều chỉnh theo phê duyệt kỹ thuật.": "For example, the marker is 8.4 m long, but the lay has been spread to only 8.32 m. If the operator stretches the fabric by a further 8 cm to match the marker, the final component may be short after the fabric recovers. The correct response is to check the reference point, actual length, roll end and marker revision. If the lay is short, rebuild it or make an adjustment approved by engineering.", "Biên bản kiểm lay nên ghi độ lệch mép lớn nhất, chiều dài lay, số lớp, tình trạng nếp, vị trí nối cuộn, lực căng theo phương pháp đánh giá và kết quả kiểm đầu/cuối. Với vật liệu nhạy cảm, có thể bổ sung kiểm tra kích thước mẫu trước và sau khi giải phóng lực.": "The lay-inspection record should include maximum edge displacement, lay length, ply count, wrinkle condition, roll-join positions, tension assessment under the defined method, and start/end inspection results. For sensitive materials, add dimensional checks on samples before and after tension release.", "Không dùng một mức lực căng hoặc dung sai lệch lớp chung cho mọi vật liệu. Các giới hạn cần xác định theo tính chất vải, chiều cao lay, thiết bị trải và tiêu chuẩn đơn hàng.": "Do not apply one tension level or ply-alignment tolerance to every material. Limits must be established according to fabric properties, lay height, spreading equipment and order specifications.", "Theo dõi lực căng, độ trượt và độ thẳng mép lớp; nếu vải bị kéo giãn hoặc đầu lớp lệch, dừng để chỉnh phương pháp trước khi cắt cả lay.": "Monitor tension, slippage and ply-edge alignment. If the fabric is stretched or the ply ends are misaligned, stop and correct the method before cutting the full lay.", "Lỗi trải là sai lệch phát sinh khi xếp lớp vải, có thể ảnh hưởng một phần hoặc toàn bộ lay. Những lỗi thường gặp gồm nếp gấp, lớp chồng không đều, lệch biên, kéo giãn, xoắn vải, sai hướng mặt, sai shade, nối cuộn không đúng và thiếu chiều dài.": "A spreading defect is a deviation introduced while laying fabric plies and may affect part or all of a lay. Common defects include wrinkles, uneven ply overlap, edge displacement, stretching, fabric twist, incorrect face orientation, shade mismatch, incorrect roll joins and insufficient length.", "Điều quan trọng là phân biệt lỗi có thể sửa trước khi cắt với lỗi đã làm thay đổi trạng thái vật liệu. Nếp gấp có thể được tháo và trải lại nếu chưa gây hằn; vải bị kéo giãn cần được giải phóng và đánh giá ổn định; sai shade hoặc sai hướng nap có thể buộc tháo toàn bộ phần lay liên quan. Không nên dùng phương án sửa tại chỗ nếu không xác định được phạm vi ảnh hưởng.": "The key is to distinguish defects that can be corrected before cutting from those that have changed the material's condition. A wrinkle may be removed and the fabric respread if it has not left a crease. Stretched fabric must be released and assessed for stability. A shade or nap-direction error may require the affected section of the lay to be dismantled. Do not attempt a local repair without first establishing the extent of the impact.", "Khi phát hiện, dừng trải hoặc cắt, đánh dấu vị trí, xác định lớp bị ảnh hưởng và ghi roll ID. Trưởng nhóm quyết định tháo lớp, trải lại, cắt bỏ đoạn lỗi hoặc cách ly lay. Sau xử lý, kiểm lại chiều dài, mép lớp, số lớp và hướng vật liệu. Nếu lỗi chỉ được phát hiện sau cắt, cần khoanh vùng theo lay, lớp và bundle trước khi cấp chuyền.": "When a defect is found, stop spreading or cutting, mark its position, identify the affected plies and record the roll ID. The team leader decides whether to dismantle plies, respread, remove the defective section or quarantine the lay. After correction, recheck length, ply edges, ply count and material orientation. If the defect is found only after cutting, isolate the affected lay, plies and bundles before issuing components to sewing.", "Ví dụ: một nếp gấp chạy qua 6 lớp ở giữa lay. Không thể chỉ vuốt phẳng lớp trên rồi tiếp tục cắt vì các lớp dưới có thể đã bị gấp theo cùng đường. Phải mở lay đến phạm vi lỗi, kiểm từng lớp, xác nhận không có hằn hoặc biến dạng rồi mới trải lại. Số chi tiết bị ảnh hưởng và thời gian sửa cần ghi vào báo cáo để phân tích nguyên nhân.": "For example, a crease runs through six plies in the middle of a lay. It is not sufficient to smooth the top ply and continue cutting, because the lower plies may have folded along the same line. Open the lay across the affected area, inspect each ply and confirm that no crease or distortion remains before respreading. Record the affected component quantity and repair time for root-cause analysis.", "Bảng lỗi nên có mã lỗi, vị trí, số lớp ảnh hưởng, roll/lay, nguyên nhân nghi ngờ, hành động khắc phục, số lượng chi tiết phải kiểm lại và người phê duyệt. Dữ liệu theo ca giúp nhận diện vấn đề do máy trải, bàn cắt, phương pháp thao tác hoặc chất lượng vải.": "The defect log should include defect code, location, number of affected plies, roll/lay, suspected cause, corrective action, quantity of components requiring reinspection and approver. Shift-level data can help identify problems caused by the spreading machine, cutting table, work method or fabric quality.", "Không đánh giá hiệu suất bộ phận trải chỉ bằng mét vải/giờ. Cần theo dõi tỷ lệ lay phải sửa, số lần dừng, phế liệu và lỗi phát hiện sau cắt.": "Do not assess spreading performance only in metres of fabric per hour. Also monitor the proportion of lays requiring correction, stoppages, waste and defects detected after cutting.", "Phân loại lỗi trải như nhăn, gấp, lệch lớp, thiếu lớp hoặc lẫn shade; xác định phạm vi lớp bị ảnh hưởng trước khi quyết định tháo, sửa hoặc loại.": "Classify spreading defects such as wrinkles, creases, ply misalignment, missing plies or mixed shades. Establish the affected ply range before deciding whether to dismantle, correct or reject the lay.", "Pattern là bộ rập xác định hình dạng và kích thước chi tiết; marker là sơ đồ bố trí các chi tiết rập trên khổ vải; cut order là lệnh sản xuất xác định số lượng cần cắt theo mã hàng, màu, cỡ và phân bổ vật liệu. Ba tài liệu liên kết chặt chẽ nhưng có chức năng khác nhau, nên phải được quản lý phiên bản riêng và đối chiếu trước khi phát hành.": "A pattern defines the shape and dimensions of a component. A marker is the layout of pattern pieces within the fabric width. A cut order is the production instruction that defines the quantities to be cut by style, colour, size and material allocation. These three documents are closely linked but serve different purposes, so each must have its own revision control and be cross-checked before release.", "Pattern cần có mã chi tiết, size, đường may, đường cắt, grainline, notch, drill mark và thông tin phiên bản. Marker phải sử dụng đúng bộ pattern đã duyệt, đúng usable width, size ratio, hướng nap và giới hạn xoay chi tiết. Cut order phải chuyển nhu cầu đơn hàng thành các lay có thể thực hiện, tính đến lot, shade, số lớp và năng lực thiết bị. Không sửa marker bằng cách dịch chi tiết thủ công mà không cập nhật bản phát hành.": "The pattern must identify the component code, size, seam line, cutting line, grainline, notches, drill marks and revision. The marker must use the approved pattern set and the correct usable width, size ratio, nap direction and component-rotation limits. The cut order must convert order demand into executable lays while accounting for lot, shade, ply count and equipment capacity. Do not move components manually on a marker without updating the released version.", "Quy trình kiểm duyệt gồm: xác nhận tech pack và pattern release; đối chiếu danh sách chi tiết; kiểm tra marker code và phiên bản; xác nhận chiều rộng, chiều dài, ratio và hướng vật liệu; kiểm tra số lượng theo cut order; phát hành bản in/điện tử có người phê duyệt. Khi có thay đổi rập, cần xác định marker, lay và bán thành phẩm đã cắt có bị ảnh hưởng hay không.": "The approval process includes confirming the tech pack and pattern release; reconciling the component list; checking the marker code and revision; verifying width, length, ratio and material orientation; checking quantities against the cut order; and releasing an approved printed or electronic copy. When a pattern changes, determine whether existing markers, lays or cut components are affected.", "Ví dụ: nhu cầu 300 áo với ratio S:M:L = 1:2:1. Một marker ratio 1:2:1 tạo bốn sản phẩm trên mỗi lớp. Để đủ 300 sản phẩm cần 75 lớp nếu toàn bộ lay dùng cùng ratio và không có phần bù; nhưng số lớp thực tế còn phải phù hợp chiều cao lay, năng lực dao cắt và phân bổ lot. Nếu thiếu một size ở cuối đơn, cut order phải thể hiện lay bổ sung riêng thay vì tự tăng lớp.": "For example, an order requires 300 garments with an S:M:L ratio of 1:2:1. A marker with that ratio produces four garments per ply. Seventy-five plies would produce 300 garments if every lay uses the same ratio and no additional quantity is required. The actual ply count must still comply with lay-height limits, cutting capacity and lot allocation. If one size is short at the end of the order, the cut order must show a separate supplementary lay rather than an unauthorised increase in ply count.", "Checklist phát hành nên có: mã sản phẩm, style/color, pattern version, marker version, usable width, ratio, chiều dài marker, số lớp, roll allocation, hướng trải, số lượng theo size và chữ ký kiểm tra. Lưu file marker cùng ảnh/bản in được duyệt để truy vết.": "The release checklist should include product code, style/colour, pattern revision, marker revision, usable width, ratio, marker length, ply count, roll allocation, spreading direction, quantities by size and inspection signatures. Retain the marker file together with the approved image or printout for traceability.", "Lỗi thường gặp là dùng marker cũ sau khi cập nhật rập, nhầm ratio, hoặc lấy số lớp làm đại diện cho số lượng sản phẩm mà không kiểm tra số bộ chi tiết trong marker. Phải kiểm tra cả cấu trúc sơ đồ và lệnh cắt.": "Common errors include using an old marker after a pattern revision, applying the wrong ratio, or treating the ply count as the garment quantity without checking how many garment sets the marker contains. Both the marker layout and the cutting instruction must be verified.", "Đối chiếu phiên bản pattern, marker, sơ đồ size và số lượng cut order; kiểm tra chi tiết đối xứng, chi tiết cặp và các notch trước khi phát hành.": "Cross-check the pattern and marker revisions, size layout and cut-order quantities. Inspect symmetrical components, paired components and notches before release.", "Grainline xác định hướng đặt chi tiết so với hướng sợi dọc, sợi ngang hoặc hướng cấu trúc của vật liệu. Bias là hướng chéo so với hai hướng sợi chính; vải cắt bias thường có khả năng biến dạng và rủ khác với chi tiết đặt theo canh sợi. Sai hướng đặt có thể làm sản phẩm xoắn, rủ không đều hoặc thay đổi kích thước sau may.": "Grainline defines a component's orientation in relation to the warp, weft or structural direction of the material. Bias is the diagonal direction across the two principal yarn directions. A bias-cut fabric can stretch and drape differently from a component placed on grain. Incorrect orientation may cause twisting, uneven drape or dimensional change after sewing.", "Với vải dệt thoi, grainline thường được xác định theo sợi dọc hoặc hướng quy định trên rập; với vải dệt kim, cần xem hướng cột vòng, hàng vòng và đặc tính co giãn. Một số chi tiết như nẹp, cổ, đáp hoặc chi tiết trang trí có thể được đặt theo hướng khác nếu thiết kế cho phép. Tuy nhiên, việc xoay chi tiết phải được kỹ thuật phê duyệt vì ảnh hưởng đến độ rủ, độ bền và ngoại quan.": "For woven fabrics, the grainline is generally defined in relation to the warp or the direction specified on the pattern. For knitted fabrics, consider the wales, courses and stretch characteristics. Some components, such as plackets, collars, facings or decorative pieces, may be placed in another direction when the design permits. However, component rotation requires engineering approval because it affects drape, strength and appearance.", "Khi kiểm rập, xác nhận mũi tên grainline, điểm chuẩn và dung sai góc đặt. Khi làm marker, khóa hướng chi tiết đối với vật liệu nhạy cảm; kiểm tra các cặp chi tiết đối xứng và các chi tiết có họa tiết. Với chi tiết bias, cần kiểm soát thao tác nhấc chuyển và thời gian ổn định trước khi may để tránh kéo dài không đồng đều.": "During pattern inspection, verify the grainline arrow, reference points and permitted angular tolerance. When preparing the marker, lock component orientation for sensitive materials and check symmetrical pairs and patterned components. For bias-cut components, control handling and the stabilisation period before sewing to avoid uneven extension.", "Ví dụ: chân váy có một số panel cắt bias. Nếu một panel bị xoay lệch góc so với các panel còn lại, chiều dài rủ sau khi treo có thể khác nhau, tạo đường gấu không cân. Trong kiểm tra mẫu, cần treo sản phẩm theo quy trình kỹ thuật, đánh dấu đường gấu sau ổn định và so sánh với yêu cầu thiết kế.": "For example, a skirt may contain several bias-cut panels. If one panel is rotated to a different angle from the others, its hanging length may change differently, producing an uneven hemline. During sample inspection, hang the garment under the specified technical procedure, mark the hem after stabilisation and compare it with the design requirement.", "Phiếu kiểm marker nên ghi grainline compliance, số chi tiết được xoay, lý do xoay, người phê duyệt và ảnh mẫu nếu cần. Với chi tiết bias, ghi rõ yêu cầu xử lý sau cắt và trước may.": "The marker inspection record should state grainline compliance, the number of rotated components, the reason for rotation, the approver and a sample image where needed. For bias-cut components, specify the required handling after cutting and before sewing.", "Không mặc định mọi chi tiết phải song song với biên vải hoặc mọi chi tiết đều có thể xoay để tăng marker efficiency. Hướng đặt là quyết định kỹ thuật gắn với cấu trúc và chức năng của sản phẩm.": "Do not assume that every component must be parallel to the selvedge or that every component can be rotated to improve marker efficiency. Orientation is an engineering decision linked to the product's construction and function.", "Kiểm tra grainline so với hướng sợi dọc, bias và hướng co giãn; các chi tiết có yêu cầu định hướng phải được đánh dấu rõ trên rập và marker.": "Check the grainline against the warp direction, bias and stretch direction. Clearly mark any orientation-sensitive components on both the pattern and marker.", "Marker efficiency phản ánh tỷ lệ diện tích chi tiết rập so với diện tích vùng marker được tính theo quy ước. Fabric utilization là mức sử dụng vật liệu thực tế sau khi tính đến các yếu tố như đầu/cuối lay, lỗi vải, biên loại bỏ, đầu nối và phần dư không thể dùng. Hai chỉ số liên quan nhưng không đồng nghĩa.": "Marker efficiency is the ratio of pattern-piece area to the marker area, calculated under a defined convention. Fabric utilisation describes actual material use after accounting for factors such as lay ends, fabric defects, discarded selvedges, roll joins and unusable remnants. The two measures are related but are not interchangeable.", "Công thức cơ bản của marker efficiency có thể biểu diễn: diện tích các chi tiết rập chia cho diện tích marker, nhân 100%. Khi so sánh, phải dùng cùng cách xác định diện tích, cùng khổ vải và cùng phiên bản rập. Hiệu suất cao hơn chưa chắc làm giảm tiêu hao thực tế nếu marker không phù hợp usable width, vải có shade band, nap direction hoặc tỷ lệ cỡ khác.": "The basic marker-efficiency formula is: total pattern-piece area divided by marker area, multiplied by 100%. Comparisons must use the same area-calculation method, fabric width and pattern revision. A higher efficiency does not necessarily reduce actual consumption if the marker does not fit the usable width or if shade bands, nap direction or size ratios impose additional constraints.", "Khi tối ưu marker, trước tiên xác nhận pattern và grainline; tiếp theo kiểm tra khoảng cách an toàn, đường cắt, hướng vật liệu, size ratio và khả năng vận hành. Chạy thử marker trên dữ liệu cuộn thực tế, không chỉ dựa vào khổ danh nghĩa. Sau cắt, đối chiếu tiêu hao dự kiến với lượng vải cấp, lượng còn lại và phế liệu có phân loại.": "When optimising a marker, first confirm the pattern and grainline. Then check cutting clearances, cutting lines, material orientation, size ratio and operational feasibility. Trial the marker using actual roll data rather than nominal width alone. After cutting, compare expected consumption with fabric issued, remaining material and classified waste.", "Ví dụ minh họa: marker dài 8,0 m trên khổ hữu dụng 1,48 m có diện tích 11,84 m². Nếu tổng diện tích các chi tiết là 9,12 m² thì marker efficiency là 77,0%. Đây là hiệu suất của sơ đồ, không phải tỷ lệ vải thành phẩm thu được; phần đầu/cuối lay, lỗi vải và hao hụt vận hành cần được tính riêng.": "Illustrative example: an 8.0 m marker on a usable width of 1.48 m has an area of 11.84 m². If the total pattern-piece area is 9.12 m², marker efficiency is 77.0%. This is the efficiency of the marker, not the proportion of fabric converted into finished garments. Lay-end losses, fabric defects and operational waste must be calculated separately.", "Báo cáo nên ghi marker length, usable width, tổng diện tích chi tiết, marker area, efficiency, size ratio, số lớp, lượng vải cấp, lượng thực dùng và phần dư. Khi thay marker, lưu cả phiên bản cũ và mới để đánh giá mức cải thiện có thể tái lập.": "The report should record marker length, usable width, total pattern-piece area, marker area, efficiency, size ratio, ply count, fabric issued, actual consumption and remnants. When a marker is revised, retain both the old and new versions so that the improvement can be assessed and reproduced.", "Không so sánh hiệu suất giữa hai style nếu một bên dùng vải một chiều còn bên kia cho phép xoay chi tiết. Cần ghi điều kiện tối ưu và các ràng buộc chất lượng.": "Do not compare efficiency between two styles if one uses one-way fabric while the other permits component rotation. Record the optimisation conditions and quality constraints.", "Đánh giá hiệu suất marker cùng usable width, chiều dài marker, khoảng cách an toàn và rủi ro shade; không tối ưu phần trăm bằng cách vi phạm yêu cầu grainline.": "Assess marker efficiency together with usable width, marker length, cutting clearance and shade risk. Do not improve the percentage by violating grainline requirements.", "Size ratio là tỷ lệ số lượng các cỡ trong một nhóm sản phẩm cần cắt. Marker planning theo size ratio nhằm bố trí các cỡ theo nhu cầu thực tế, giảm số lay bổ sung và hạn chế tồn dư cỡ không cân đối. Một marker có hiệu suất tốt nhưng ratio không khớp nhu cầu sẽ tạo ra chi tiết thừa ở một số cỡ và thiếu ở cỡ khác.": "Size ratio is the proportion of sizes required within a group of garments to be cut. Marker planning by size ratio arranges sizes according to actual demand, reduces supplementary lays and limits unbalanced size leftovers. A highly efficient marker with a ratio that does not match demand will create excess components in some sizes and shortages in others.", "Trước khi lập marker, merchandising/production planning phải xác nhận số lượng theo style, màu, size và đợt giao. Marker maker cần xác định ratio phù hợp, số sản phẩm tạo ra trên mỗi lớp và cách chia lay. Với đơn hàng không chia hết theo ratio, phần chênh được lập thành lay bổ sung hoặc marker ratio khác; không nên cố gộp mọi cỡ vào một sơ đồ nếu làm tăng phế liệu hoặc gây khó kiểm soát.": "Before marker planning, merchandising or production planning must confirm quantities by style, colour, size and delivery lot. The marker maker determines a suitable ratio, garments produced per ply and the lay split. If the order quantity is not divisible by the ratio, handle the balance through a supplementary lay or a different marker ratio. Do not force every size into one layout if this increases waste or makes control difficult.", "Ví dụ: nhu cầu 500 sản phẩm có ratio XS:S:M:L = 1:2:3:2, tổng 8 sản phẩm mỗi bộ ratio. 62 bộ tạo 496 sản phẩm; còn 4 sản phẩm cần một phương án riêng. Nếu marker được thiết kế cho 8 sản phẩm/lớp, kế hoạch 62 lớp chưa đủ 500. Cut order phải ghi rõ 496 sản phẩm từ lay chính và 4 sản phẩm từ lay bổ sung, kèm kiểm soát lot và shade.": "For example, demand is 500 garments with an XS:S:M:L ratio of 1:2:3:2, or eight garments per ratio set. Sixty-two sets produce 496 garments, leaving four garments to be planned separately. If the marker produces eight garments per ply, a 62-ply plan does not reach 500. The cut order must show 496 garments from the main lay and four from a supplementary lay, with lot and shade control maintained.", "Khi đánh giá phương án, xem xét số lượng lớp, chiều cao lay, chiều dài marker, hiệu suất, số lần đổi marker và khả năng phối kiện. Nếu một màu có ratio khác màu còn lại, cần lập kế hoạch riêng thay vì lấy ratio trung bình toàn đơn hàng.": "When evaluating a plan, consider ply count, lay height, marker length, efficiency, the number of marker changes and bundling feasibility. If one colour has a different ratio from the others, plan it separately rather than using an average ratio for the entire order.", "Bảng marker plan nên có nhu cầu từng size, ratio marker, sản phẩm/lớp, số lớp, số lượng tạo ra, chênh lệch và phương án xử lý. Người duyệt phải xác nhận cả tổng số lượng lẫn phân bổ theo cỡ.": "The marker plan should show demand by size, marker ratio, garments per ply, ply count, output quantity, variance and the proposed disposition. The approver must confirm both the total quantity and the size allocation.", "Lỗi phổ biến là làm tròn số lớp rồi không đối chiếu số lượng cuối cùng, hoặc lấy ratio dự báo thay cho ratio đơn hàng đã xác nhận. Mọi thay đổi đơn hàng phải kích hoạt kiểm tra lại marker plan.": "Common errors include rounding the ply count without reconciling the final quantity, or using a forecast ratio instead of the confirmed order ratio. Every order change must trigger a review of the marker plan.", "Đối chiếu tỷ lệ size trong marker với PO và kế hoạch giao hàng; lưu số lượng mỗi size, số lay và phần dư để tránh lệch cơ cấu khi cấp bundle.": "Reconcile the marker size ratio with the PO and delivery plan. Record quantities by size, lay count and balance quantities to prevent size imbalance during bundle issue.", "Máy cắt đầu bàn và dao cắt tay thường được sử dụng để cắt tách lay, cắt đoạn, chỉnh mép hoặc xử lý các chi tiết mà máy cắt lớn không thuận tiện tiếp cận. Việc lựa chọn phụ thuộc độ dày lay, độ chính xác, hình dạng chi tiết và mức độ lặp lại của thao tác.": "End-cutters and hand-held cutting tools are commonly used to separate lays, cut sections, trim edges or handle components that are difficult to reach with larger cutting machines. Selection depends on lay thickness, required accuracy, component shape and task repeatability.", "Máy cắt đầu bàn có thể hỗ trợ cắt theo đường dẫn hoặc cắt đoạn ở khu vực bàn trải; dao cắt tay phù hợp với một số thao tác nhỏ nhưng phụ thuộc nhiều vào kỹ năng người dùng. Cần phân biệt thiết bị cắt sản xuất với dao thủ công dùng để sửa/trim. Lưỡi, bộ bảo vệ, tay cầm và cơ cấu dừng phải phù hợp với mục đích và quy định an toàn của nhà máy.": "An end-cutter may support guided cuts or sectioning at the spreading table. A hand-held knife may suit certain small tasks, but its result depends heavily on operator skill. Production cutting equipment must be distinguished from hand tools used for repair or trimming. The blade, guard, handle and stopping mechanism must suit the intended task and the factory's safety requirements.", "Trước khi cắt, xác nhận marker và đường cắt, kiểm tra vật liệu được cố định, loại bỏ vật cản và bố trí tư thế thao tác an toàn. Cắt thử trên mẫu đại diện, kiểm độ vuông, mép cắt và hiện tượng xô lớp. Không dùng dao cùn hoặc lưỡi không đúng chủng loại vì lực đẩy tăng và đường cắt dễ lệch.": "Before cutting, confirm the marker and cutting line, ensure the material is secured, remove obstructions and establish a safe working position. Make a trial cut on a representative sample and check squareness, edge quality and ply movement. Do not use a blunt or incorrect blade type, as it increases pushing force and makes cutting deviation more likely.", "Ví dụ: khi tách lay theo đường thẳng, máy đầu bàn có thể phù hợp hơn dao tay nếu chiều dài và độ lặp lại cao. Với chi tiết nhỏ hoặc đường cong, cần thử dưỡng và phương pháp giữ vật liệu để tránh kéo lệch. Nếu công việc đòi hỏi cắt xuyên nhiều lớp, phải xác nhận khả năng thiết bị theo manual, không suy đoán từ công suất motor.": "For a long, repetitive straight cut, an end-cutter may be more suitable than a hand-held knife. For small components or curves, trial the template and material-holding method to prevent distortion. If the task requires cutting through multiple plies, verify the machine's capability against its manual; do not infer it from motor power.", "Phiếu kiểm cần ghi loại máy/dao, loại lưỡi, vật liệu, số lớp, mục đích, người vận hành, kiểm tra bảo vệ và kết quả mẫu đầu. Lưỡi thay thế phải được quản lý và lưu trữ an toàn.": "The inspection record should state the machine or knife type, blade type, material, ply count, purpose, operator, guard inspection and first-sample result. Replacement blades must be controlled and stored safely.", "Không dùng dao tay để bù cho marker sai hoặc lay không ổn định. Khi đường cắt không đạt, tìm nguyên nhân ở dữ liệu, cố định vật liệu, độ sắc lưỡi và phương pháp thao tác.": "Do not use a hand-held knife to compensate for an incorrect marker or unstable lay. If the cut is unacceptable, investigate the data, material restraint, blade sharpness and work method.", "Kiểm tra lưỡi, tấm đế, bảo vệ, dây nguồn và vùng thao tác trước ca; chọn thiết bị theo chiều cao lay, bán kính đường cắt và yêu cầu an toàn.": "Before each shift, inspect the blade, base plate, guard, power cable and work area. Select equipment according to lay height, cutting radius and safety requirements.", "Straight knife và round knife là hai nhóm máy cắt di động thường dùng trong phòng cắt, nhưng khả năng làm việc khác nhau theo chiều cao lay, hình dạng chi tiết, bán kính cong và vật liệu. Việc chọn máy cần dựa trên cấu trúc lay và yêu cầu độ chính xác, không chỉ dựa vào tốc độ hoặc mức độ quen thuộc của người vận hành.": "Straight-knife and round-knife machines are two common mobile cutting-machine types in a cutting room. Their capabilities differ according to lay height, component shape, curve radius and material. Machine selection should be based on lay construction and accuracy requirements, not only speed or operator familiarity.", "Straight knife dùng lưỡi dao chuyển động tịnh tiến, phù hợp với nhiều dạng đường cắt và lay có chiều cao nằm trong giới hạn thiết bị. Khi cắt đường cong nhỏ hoặc góc hẹp, người vận hành phải kiểm soát hướng tiến, độ nghiêng và độ ổn định của dao để tránh xô lớp. Round knife dùng lưỡi tròn quay, thường phù hợp hơn với đường cắt dài, tương đối thẳng và lay thấp; khả năng xử lý góc nhỏ bị giới hạn bởi đường kính dao và hình học máy.": "A straight knife uses a reciprocating blade and can handle many cutting paths and lays within the machine's specified height limit. When cutting tight curves or narrow corners, the operator must control feed direction, blade inclination and stability to prevent ply displacement. A round knife uses a rotating circular blade and is generally better suited to long, relatively straight cuts in low lays; its ability to negotiate tight corners is limited by blade diameter and machine geometry.", "Trước ca, kiểm tra lưỡi dao, bộ bảo vệ, dây điện/nguồn, hệ thống mài, chân đế và khu vực làm việc. Kiểm tra lay đã được cố định, marker đúng phiên bản và chiều cao không vượt giới hạn manual. Cắt thử ở vùng mẫu hoặc phần dư, kiểm tra độ vuông thành lớp và độ sạch mép cắt. Chỉ người được huấn luyện mới vận hành; không đưa tay vào vùng lưỡi hoặc tháo bộ phận bảo vệ khi máy đang chạy.": "Before the shift, inspect the blade, guard, power supply, sharpening system, base and work area. Confirm that the lay is secured, the marker revision is correct and the lay height does not exceed the manual's limit. Make a trial cut in a sample area or on waste material, then check ply squareness and cut-edge quality. Only trained personnel may operate the machine. Never place a hand near the blade or remove a guard while the machine is running.", "Ví dụ lựa chọn: lay thấp, đường cắt dài và ít góc gấp có thể phù hợp round knife; lay dày hơn hoặc chi tiết có nhiều đường cong thường cần đánh giá straight knife hoặc thiết bị chuyên dụng. Đây chỉ là định hướng sơ bộ; giới hạn thực tế phải lấy từ manual của model máy, loại dao và vật liệu.": "As a preliminary selection guide, a low lay with long cuts and few tight corners may suit a round knife. A thicker lay or components with many curves may require evaluation of a straight knife or specialised equipment. Actual limits must be taken from the manual for the specific machine model, blade and material.", "Bảng lựa chọn thiết bị cần ghi chiều cao lay, loại vải, độ cong nhỏ nhất, yêu cầu notch, độ chính xác, model máy, loại lưỡi và kết quả cắt thử. Theo dõi độ mòn lưỡi và chất lượng mép cắt theo ca.": "The equipment-selection record should state lay height, fabric type, minimum curve radius, notch requirements, accuracy, machine model, blade type and trial-cut results. Monitor blade wear and cut-edge quality by shift.", "Không tăng chiều cao lay vượt khuyến nghị để giảm số lần trải. Lay quá cao có thể làm dao lệch, lớp dưới không được cắt sạch và tăng rủi ro an toàn.": "Do not exceed the recommended lay height to reduce the number of spreading cycles. An excessively high lay can deflect the blade, leave lower plies incompletely cut and increase safety risks.", "Chọn loại dao theo chiều cao lay, hình dạng đường cắt và khả năng điều khiển; kiểm tra độ sắc, độ vuông góc và độ ổn định của mép chi tiết sau cắt.": "Select the knife type according to lay height, cutting-path geometry and controllability. After cutting, check blade sharpness, squareness and cut-edge stability.", "Band knife sử dụng lưỡi dao dạng băng chạy liên tục qua bàn cắt, thường được dùng để cắt chính xác các chi tiết nhỏ hoặc cụm chi tiết đã được bó/định hình. Khả năng ứng dụng phụ thuộc cách gá vật liệu, dưỡng dẫn, độ ổn định của lưỡi và kỹ năng đưa chi tiết qua vùng cắt.": "A band knife uses a continuous loop blade running through the cutting table. It is commonly used for precise cutting of small components or component stacks that have been bundled or shaped. Its suitability depends on material fixturing, guide templates, blade stability and the operator's ability to feed the material through the cutting zone.", "Ưu điểm của band knife là đường cắt liên tục và khả năng kiểm soát chi tiết nhỏ khi có dưỡng phù hợp. Tuy nhiên, máy đòi hỏi kiểm soát độ căng lưỡi, độ vuông bàn, hướng cấp liệu và vùng bảo vệ. Chi tiết mềm, trơn hoặc có nhiều lớp dễ bị xê dịch nếu không được cố định. Dưỡng cắt phải đảm bảo không làm tay người vận hành tiến gần lưỡi và không tạo lực làm biến dạng vật liệu.": "A band knife provides a continuous cutting action and can control small components when a suitable template is used. However, blade tension, table squareness, feed direction and guarding must be controlled. Soft, slippery or multilayer components may shift if they are not secured. The cutting template must keep the operator's hands away from the blade and must not apply force that distorts the material.", "Trước khi chạy, kiểm tra lưỡi có nứt/mẻ, độ căng theo hướng dẫn máy, cơ cấu dẫn hướng, bộ bảo vệ, bàn đỡ và công tắc dừng. Chạy thử không tải theo quy trình an toàn; sau đó cắt mẫu và kiểm kích thước, góc vuông, mép cắt và dấu định vị. Với chi tiết cần cặp trái/phải, kiểm tra hướng đặt và nhận diện để không tạo hai chi tiết cùng bên.": "Before operation, check the blade for cracks or chips, verify tension according to the machine instructions, and inspect guides, guards, support table and stop switch. Conduct a no-load test under the safety procedure, then cut a sample and check dimensions, squareness, edge quality and locating marks. For left/right pairs, verify orientation and identification to avoid producing two components for the same side.", "Ví dụ: khi cắt nhiều lớp chi tiết túi nhỏ, nếu chồng lớp không được cố định, lớp dưới có thể trượt và tạo sai lệch hình dạng. Giải pháp không phải ép tay mạnh hơn mà là dùng dưỡng/đồ gá phù hợp, giảm chiều cao chồng nếu cần và kiểm tra mẫu ở lớp trên, giữa, dưới.": "When cutting multiple plies of small pocket components, an unsecured stack may allow the lower plies to slip and distort the shape. The solution is not to press harder by hand. Use a suitable template or fixture, reduce stack height if necessary and inspect samples from the top, middle and bottom plies.", "Hồ sơ máy cần ghi model, loại lưỡi, lịch thay lưỡi, kiểm tra bảo vệ, dưỡng tương ứng, sản phẩm được phép chạy và người được ủy quyền. Kết quả kiểm đầu ca cần lưu cùng mã hàng.": "The machine record should include model, blade type, blade-replacement schedule, guard inspection, associated templates, approved product types and authorised operators. Retain the start-of-shift inspection result with the style record.", "Không sử dụng band knife như giải pháp thay thế cho mọi chi tiết nhỏ. Nếu chi tiết có vật liệu dễ trượt, yêu cầu dung sai cao hoặc đường cong phức tạp, cần thử nghiệm và phê duyệt phương pháp riêng.": "Do not use a band knife as a universal solution for all small components. If the material is slippery, the tolerance is tight or the cutting path is complex, trial and approve a specific method.", "Xác nhận cữ dẫn, vùng che chắn và phương pháp cấp chi tiết; dùng mẫu đầu để kiểm tra kích thước, độ vuông góc và độ ổn định trước khi cắt hàng loạt.": "Verify the guide, guarding and component-feed method. Use a first-off sample to check dimensions, squareness and stability before production cutting.", "Garment Academy | Cutting & Pre-production": "Garment Academy | Cutting & Pre-production", "🛠️ ỨNG DỤNG": "🛠️ APPS", "🎮 TRÒ CHƠI": "🎮 GAMES", "🧰 CÔNG CỤ": "🧰 TOOLS", "✨ AI": "✨ AI", "Khu AI": "AI Hub", "🎟️ XỔ SỐ": "🎟️ LOTTERY", "🛍️ ĐI CHỢ": "🛍️ SHOPPING", "📰 TIN TỨC": "📰 NEWS", "📚 HỌC VIỆN MAY MẶC": "📚 GARMENT ACADEMY", "Garment Academy": "Garment Academy", "AppNho": "AppNho", "AppNho Garment Academy · Chuyên đề 08": "AppNho Garment Academy · Module 08", "Phạm vi ở đây kết thúc tại việc chuẩn bị và bàn giao bán thành phẩm đạt yêu cầu: kiểm vải, relaxation, spreading, marker, cutting, numbering, bundling và fusing. Việc vận hành máy, bố trí chuyền và cân bằng công đoạn thuộc": "This module ends with the preparation and handover of conforming cut components: fabric inspection, relaxation, spreading, marker preparation, cutting, numbering, bundling and fusing. Machine operation, line layout and operation balancing are covered in", "Phase 9 – quản lý chuyền may": "Phase 9 – Sewing Production Management", "Phase 7 – máy móc ngành may": "Phase 7 – Garment Machinery", ". Giữ liên kết truy xuất giữa lot vải, sơ đồ cắt, bó hàng và lệnh sản xuất để tránh đứt thông tin khi bàn giao.": ". Maintain traceability links among fabric lots, cutting markers, bundles and production orders so that information is not lost at handover.", "Kiểm vải": "Fabric inspection", "Lot · shade · lỗi": "Lot · shade · defects", "Relax & trải": "Relaxation & spreading", "Lay · ply · tension": "Lay · ply · tension", "Marker": "Marker", "Pattern · grainline": "Pattern · grainline", "Cắt": "Cutting", "Knife · CNC": "Knife · CNC", "Numbering": "Numbering", "Shade trace": "Shade traceability", "Bundling": "Bundling", "Ticket · sewing": "Ticket · sewing", "Mỗi bước cần truy xuất lot, phiên bản tài liệu và trạng thái kiểm tra": "Every step must retain lot traceability, document revision and inspection status", "Không tìm thấy bài phù hợp. Thử từ khóa khác.": "No matching lesson was found. Try another search term.", "Lectra – Knowledge and resources": "Lectra – Knowledge and resources", "về CAD, marker making và cắt tự động.": "on CAD, marker making and automated cutting.", "Gerber Technology": "Gerber Technology", "– giải pháp CAD, marker và automated cutting.": "– CAD, marker-making and automated-cutting solutions.", "ASTM International": "ASTM International", "– tra cứu phương pháp thử vật liệu dệt.": "– consult test methods for textile materials.", "ISO": "ISO", "– tra cứu tiêu chuẩn hiện hành theo phương pháp thử.": "– consult current standards relevant to the test method.", "Lưu ý:": "Note:", "Hệ thống 4-point, thời gian relaxation, dung sai cắt, định mức hao hụt và điều kiện fusing phải theo tiêu chuẩn nhà máy/khách hàng và tài liệu vật liệu. Không dùng một con số mặc định cho mọi loại vải.": "The 4-Point System, relaxation time, cutting tolerances, loss allowances and fusing conditions must follow factory or customer standards and material documentation. Do not apply one default value to every fabric.", "© 2026 AppNho · Garment Academy": "© 2026 AppNho · Garment Academy", "Bài 01 / 27": "Lesson 01 / 27", "Bài 02 / 27": "Lesson 02 / 27", "Bài 03 / 27": "Lesson 03 / 27", "Bài 04 / 27": "Lesson 04 / 27", "Bài 05 / 27": "Lesson 05 / 27", "Bài 06 / 27": "Lesson 06 / 27", "Bài 07 / 27": "Lesson 07 / 27", "Bài 08 / 27": "Lesson 08 / 27", "Bài 09 / 27": "Lesson 09 / 27", "Bài 10 / 27": "Lesson 10 / 27", "Bài 11 / 27": "Lesson 11 / 27", "Bài 12 / 27": "Lesson 12 / 27", "Bài 13 / 27": "Lesson 13 / 27", "Bài 14 / 27": "Lesson 14 / 27", "Bài 15 / 27": "Lesson 15 / 27", "Bài 16 / 27": "Lesson 16 / 27", "Bài 17 / 27": "Lesson 17 / 27", "Bài 18 / 27": "Lesson 18 / 27", "Bài 19 / 27": "Lesson 19 / 27", "Bài 20 / 27": "Lesson 20 / 27", "Bài 21 / 27": "Lesson 21 / 27", "Bài 22 / 27": "Lesson 22 / 27", "Bài 23 / 27": "Lesson 23 / 27", "Bài 24 / 27": "Lesson 24 / 27", "Bài 25 / 27": "Lesson 25 / 27", "Bài 26 / 27": "Lesson 26 / 27", "Bài 27 / 27": "Lesson 27 / 27"};
  var pageTitle = {vi:"Garment Academy | Cutting & Pre-production",en:"Garment Academy | Fabric Cutting and Pre-production"};
  var pageDescription = {vi:"Chuyên đề chuẩn bị sản xuất, kiểm tra vải, spreading, marker planning, cutting, numbering, bundling, fusing và bàn giao bán thành phẩm.",en:"A technical guide to pre-production preparation, incoming fabric inspection, spreading, marker planning, cutting, numbering, bundling, fusing and cut-component handover."};
  var dictionary = Object.create(null), index = 0;
  function makeKey(kind){ index += 1; return 'phase8.' + kind + '.' + index; }
  function translatedValue(source){
    var leading=(source.match(/^\s*/) || [''])[0], trailing=(source.match(/\s*$/) || [''])[0];
    var trimmed=source.replace(/\\s+/g,' ').trim();
    if(!Object.prototype.hasOwnProperty.call(translations,trimmed)) return null;
    return {leading:leading,trailing:trailing,value:translations[trimmed]};
  }
  function makeTablesScrollable(){
    document.querySelectorAll('table').forEach(function(table){
      if(table.closest('.bilingual-table-scroll')) return;
      var wrapper=document.createElement('div');
      wrapper.className='bilingual-table-scroll';
      table.parentNode.insertBefore(wrapper,table);
      wrapper.appendChild(table);
    });
  }
  function annotateText(){
    var walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT), nodes=[], node;
    while((node=walker.nextNode())) nodes.push(node);
    nodes.forEach(function(textNode){
      var parent=textNode.parentElement;
      if(!parent || /^(SCRIPT|STYLE|NOSCRIPT|TEMPLATE)$/.test(parent.tagName)) return;
      if(parent.closest && parent.closest('[data-i18n]')) return;
      var result=translatedValue(textNode.nodeValue);
      if(!result) return;
      var k=makeKey('text'); dictionary[k]=result.leading+result.value+result.trailing;
      if(parent.namespaceURI==='http://www.w3.org/2000/svg'){
        if(/^(text|tspan|title)$/i.test(parent.tagName) && parent.childNodes.length===1) parent.setAttribute('data-i18n',k);
        else { var span=document.createElementNS('http://www.w3.org/2000/svg','tspan'); span.setAttribute('data-i18n',k); span.textContent=textNode.nodeValue; parent.replaceChild(span,textNode); }
      } else { var span=document.createElement('span'); span.setAttribute('data-i18n',k); span.textContent=textNode.nodeValue; parent.replaceChild(span,textNode); }
    });
  }
  function annotateAttributes(){
    ['title','placeholder','aria-label','alt'].forEach(function(attr){
      document.body.querySelectorAll('*').forEach(function(el){
        var source=el.getAttribute(attr); if(!source) return;
        var result=translatedValue(source); if(!result) return;
        var k=makeKey('attr'); dictionary[k]=result.value;
        if(attr==='alt'){el.setAttribute('data-i18n-alt',k);el.setAttribute('data-i18n-source-alt',source);}
        else el.setAttribute('data-i18n-'+attr,k);
      });
    });
  }
  function updateDynamicCount(){
    var count=document.getElementById('count');
    if(!count) return;
    var raw=count.textContent||'', match=raw.match(/(\d+)\s*\/\s*(\d+)/);
    if(!match){
      var cards=Array.prototype.slice.call(document.querySelectorAll('.lesson'));
      if(!cards.length) return;
      var visible=cards.filter(function(card){return !card.hidden;}).length;
      match=[null,String(visible),String(cards.length)];
    }
    var lang=window.AppNhoI18n?window.AppNhoI18n.getLanguage():'vi';
    var desired=lang==='en' ? ('Showing '+match[1]+'/'+match[2]+' lessons') : ('Đang hiển thị '+match[1]+'/'+match[2]+' bài học');
    if(raw!==desired) count.textContent=desired;
  }
  function updateMeta(){
    var lang=window.AppNhoI18n?window.AppNhoI18n.getLanguage():'vi';
    document.title=pageTitle[lang]||pageTitle.vi;
    var meta=document.querySelector('meta[name="description"]');
    if(meta) meta.setAttribute('content',pageDescription[lang]||pageDescription.vi);
    document.body.querySelectorAll('[data-i18n-alt]').forEach(function(el){
      var k=el.getAttribute('data-i18n-alt');
      el.setAttribute('alt',lang==='en' && Object.prototype.hasOwnProperty.call(dictionary,k)?dictionary[k]:(el.getAttribute('data-i18n-source-alt')||''));
    });
    updateDynamicCount();
  }
  makeTablesScrollable();
  annotateText(); annotateAttributes();
  if(window.AppNhoI18n){ window.AppNhoI18n.register('en',dictionary); window.AppNhoI18n.setPageReady(true); }
  updateMeta();
  var countNode=document.getElementById('count');
  if(countNode && window.MutationObserver){
    var countObserver=new MutationObserver(updateDynamicCount);
    countObserver.observe(countNode,{childList:true,characterData:true,subtree:true});
  }
  window.addEventListener('appnho:languagechange',updateMeta);
  document.addEventListener('DOMContentLoaded',updateMeta,{once:true});
})();
